insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('an-aaa-ach', 'en', array['NHS web page with a full staged loading programme for Achilles pain, each with a video.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('an-aaa-oa', 'en', array['NHS web page about ankle osteoarthritis, exercise and self-management.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('an-aaa-pf', 'en', array['NHS web page with stretching, loading and footwear advice videos for heel pain.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('an-aaa-sprain', 'en', array['NHS web page with mobility, stretching, strengthening and balance videos after a sprain.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('an-ach-devon', 'en', array['Explains Achilles tendon pain and why loading exercise helps.', 'Includes a staged exercise programme.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('an-ach-ecc', 'en', array['Stand on the edge of a step on the balls of both feet, holding a rail.', 'Rise up on both feet, then take the good foot off.', 'Lower slowly on the painful leg until the heel is below the step.', 'Do 3 sets of 15.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('an-ach-iso', 'en', array['Sit with feet flat and a weight or your hands pressing down on your knees.', 'Push up through the balls of your feet so the heels lift slightly, and hold.', 'Hold 10 seconds in week 1, building to 40 seconds by week 4.', 'Repeat 5 times, 4 times a day.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('an-ach-raise', 'en', array['Stand holding a support.', 'Rise up onto your toes on both feet, then lower slowly.', 'Keep your knees straight.', 'Do 3 sets of 15.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('an-ach-raise', 'ha', array['Tsaya kana riƙe da wani abu.', 'Ka tashi kan yatsun ƙafafu biyu, sannan ka sauko a hankali.', 'Gwiwoyinka su kasance a miƙe.', 'Yi zagaye uku na 15.']::text[], null, null, 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('an-ach-raise', 'ig', array['Guzoro jide ihe.', 'Bilie n''elu mkpịsị ụkwụ abụọ, wee jiri nwayọ wedata.', 'Mee ka ikpere gị kwụ ọtọ.', 'Mee usoro atọ nke 15.']::text[], null, null, 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('an-ach-raise', 'yo', array['Dúró kí o di nǹkan mú.', 'Dìde sórí ìka ẹsẹ̀ méjèèjì, lẹ́yìn náà rọra sọ̀ kalẹ̀.', 'Jẹ́ kí orúnkún rẹ wà ní tààrà.', 'Ṣe ìpele mẹ́ta ti 15.']::text[], null, null, 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('an-ach-towel', 'en', array['Sit with your leg straight and a towel around the ball of your foot.', 'Pull gently until you feel a stretch in the calf.', 'Hold 30 seconds.', 'Repeat 3 times, 4 times a day.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('an-acute', 'en', array['Printable staged programme after an ankle sprain, from early movement to return to sport.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('an-band', 'en', array['Sit with a resistance band around your foot.', 'Move the foot down, up, in and out against the band.', 'Return slowly each time.', 'Do 10 to 15 repetitions in each direction.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('an-calf-nuh', 'en', array['Sit with your leg straight and a towel around the ball of the foot.', 'Pull the towel gently towards you.', 'Feel the stretch in the calf.', 'Hold 30 seconds, repeat 3 times.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('an-heelraise', 'en', array['Stand holding a support with feet hip-width apart.', 'Rise up onto your toes, then lower slowly.', 'Keep your weight through the big toe.', 'Do 3 sets of 10 to 15.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('an-heelraise', 'ha', array['Tsaya kana riƙe da wani abu, ƙafafunka a buɗe daidai da kugu.', 'Ka tashi kan yatsun ƙafa, sannan ka sauko a hankali.', 'Nauyinka ya kasance a kan babban yatsan ƙafa.', 'Yi zagaye uku na 10 zuwa 15.']::text[], null, null, 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('an-heelraise', 'ig', array['Guzoro jide ihe, ụkwụ gị gbasaa dị ka úkwù.', 'Bilie n''elu mkpịsị ụkwụ gị, wee jiri nwayọ wedata.', 'Mee ka ibu gị dị na nnukwu mkpịsị ụkwụ.', 'Mee usoro atọ nke 10 ruo 15.']::text[], null, null, 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('an-heelraise', 'yo', array['Dúró kí o di nǹkan mú, kí ẹsẹ̀ rẹ jìnnà síra bí ìbàdí.', 'Dìde sórí ìka ẹsẹ̀ rẹ, lẹ́yìn náà rọra sọ̀ kalẹ̀.', 'Jẹ́ kí ìwúwo rẹ wà lórí àtàǹpàkò ẹsẹ̀.', 'Ṣe ìpele mẹ́ta ti 10 sí 15.']::text[], null, null, 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('an-impinge', 'en', array['Printable programme of ankle movement, calf stretches, strength and balance exercises.', 'Start with seated exercises and progress to balance and lunges.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('an-intrinsic-yt', 'en', array['Sit with your foot flat on the floor.', 'Short foot: gently draw the ball of the foot towards the heel to lift the arch without curling the toes.', 'Toe lifts: lift the big toe while the others stay down, then lift the other toes.', 'Do 10 repetitions of each, once a day.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('an-intrinsic', 'en', array['Sit with your foot flat on a towel on the floor.', 'Scrunch your toes to pull the towel towards you.', 'Relax and repeat.', 'Do 3 to 5 times.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('an-iso-pf', 'en', array['Sit with a towel or band around the ball of your foot.', 'Push your foot down into the towel without moving.', 'Hold 10 seconds, building to 40 seconds over 4 weeks.', 'Repeat 5 times, 3 to 4 times a day.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('an-pf-load', 'en', array['Stand on a step with a rolled towel under your toes so they bend up.', 'Rise up onto your toes slowly over 3 seconds, hold 2 seconds, lower over 3 seconds.', 'Hold a support for balance.', 'Do 3 sets of about 12, every second day.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('an-pf-towel', 'en', array['Sit with your leg straight and a towel around the ball of your foot.', 'Pull the towel gently towards you to stretch the sole and calf.', 'Hold 20 seconds.', 'Repeat 3 times.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('an-pf-towel', 'ha', array['Zauna ƙafarka a miƙe, tawul ya zagaye gaban tafin ƙafarka.', 'A hankali ka jawo tawul ɗin zuwa gare ka don miƙe tafin ƙafa da ƙwauri.', 'Riƙe na daƙiƙa 20.', 'Yi sau uku.']::text[], null, null, 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('an-pf-towel', 'ig', array['Nọdụ ala, ụkwụ gị setịpụrụ ọtọ, akwa nhicha gbara n''ihu ụkwụ gị gburugburu.', 'Jiri nwayọ dọta akwa ahụ gaa n''ebe ị nọ iji gbatịa ala ụkwụ na ọbụ ụkwụ.', 'Jide ya sekọnd 20.', 'Mee ya ugboro atọ.']::text[], null, null, 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('an-pf-towel', 'yo', array['Jókòó kí ẹsẹ̀ rẹ na tààrà, kí aṣọ ìnura yí iwájú àtẹ́lẹsẹ̀ rẹ ká.', 'Rọra fa aṣọ náà sí ọ̀dọ̀ rẹ láti fa àtẹ́lẹsẹ̀ àti ẹsẹ̀-ẹ̀yìn.', 'Dì í mú fún ìṣẹ́jú-àáyá 20.', 'Ṣe é ní ìgbà mẹ́ta.']::text[], null, null, 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('an-pf-uw', 'en', array['Printable patient handout of stretches and strengthening for heel pain.', 'Stretch first thing in the morning before standing.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('an-pf-wall', 'en', array['Stand facing a wall and place your toes up against it with the heel on the floor.', 'Lean gently forwards to stretch the sole of the foot.', 'Hold 20 seconds.', 'Repeat 3 times.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('an-pt', 'en', array['Start with seated exercises: turn the foot inwards against a band.', 'Progress to heel raises with a ball between the heels.', 'Keep the arch lifted during movements.', 'Do 10 to 15 repetitions, 2 to 3 sets.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('an-rot', 'en', array['Sit with your foot off the floor.', 'Draw slow circles with your foot, one way and then the other.', 'Move as far as is comfortable.', 'Do 20 to 30 each way, every 2 hours as pain allows.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('an-slb', 'en', array['Stand near a support on the injured leg.', 'Lift the other foot and balance.', 'Hold as long as you can, aiming for 60 seconds.', 'When easy, try with eyes closed or on a pillow.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('an-slb', 'ha', array['Tsaya kusa da abin riƙewa, a kan ƙafar da ta ji rauni.', 'Ka ɗaga ɗayan ƙafar ka tsaya daidai.', 'Ka riƙe har iyakar da za ka iya, burinka daƙiƙa 60.', 'Idan ya yi sauƙi, gwada da rufe ido ko a kan matashin kai.']::text[], null, null, 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('an-slb', 'ig', array['Guzoro n''akụkụ ihe ị ga-ejide, n''ụkwụ merụrụ ahụ.', 'Bulie ụkwụ nke ọzọ, kwụsie ike.', 'Jide ya ogologo oge ị nwere ike, chọọ iru sekọnd 60.', 'Mgbe ọ dị mfe, nwalee ya mechie anya ma ọ bụ n''elu ohiri isi.']::text[], null, null, 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('an-slb', 'yo', array['Dúró nítòsí nǹkan tí o lè dì mú, lórí ẹsẹ̀ tí ó farapa.', 'Gbé ẹsẹ̀ kejì sókè kí o sì dúró déédéé.', 'Dì í mú bí o ti lè ṣe tó, kí o fojú sí ìṣẹ́jú-àáyá 60.', 'Nígbà tí ó bá rọrùn, gbìyànjú pẹ̀lú ojú dídì tàbí lórí ìrọ̀rí.']::text[], null, null, 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('an-tandem-walk', 'en', array['Stand next to a wall or kitchen worktop.', 'Walk forwards placing the heel of one foot directly in front of the toes of the other.', 'Walk 4 metres, turn and come back.', 'Repeat 3 to 4 times.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('cp-elders-1', 'en', array['Follow along with this gentle seated and standing session.', 'Keep a chair nearby for support.', 'Move within comfort and rest when you need to.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('cp-elders-2', 'en', array['Follow along with gentle joint movements for the whole body.', 'Do each movement slowly and comfortably.', 'Good for daily practice.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('cp-elders-3', 'en', array['A short daily mobility routine.', 'Can be done seated or standing with support.', 'Do it once or twice a day.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('cp-fibro-st', 'en', array['Follow along with this gentle 15-minute stretch routine.', 'Move slowly and breathe calmly.', 'Skip any stretch that feels too much today.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('cp-fibro', 'en', array['Exercise is one of the most effective treatments for fibromyalgia.', 'Start very small, such as 5 minutes of walking.', 'Increase slowly and plan rest. Some soreness is expected at first.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('cp-fibro', 'ha', array['Motsa jiki yana ɗaya daga cikin mafi kyawun magunguna na fibromyalgia.', 'Fara kaɗan sosai, kamar tafiya na minti 5.', 'Ka ƙara a hankali kuma ka tsara hutu. Ana iya jin ɗan ciwo a farko.']::text[], null, null, 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('cp-fibro', 'ig', array['Mmega ahụ bụ otu n''ime ọgwụgwọ kacha arụ ọrụ maka fibromyalgia.', 'Malite obere obere, dị ka ịga ije nkeji 5.', 'Na-agbakwunye nwayọ, hazie ezumike. Ahụ nwere ike ịfụ ụfụ ntakịrị na mbụ.']::text[], null, null, 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('cp-fibro', 'yo', array['Eré-ìdárayá jẹ́ ọ̀kan lára ìtọ́jú tó dára jùlọ fún fibromyalgia.', 'Bẹ̀rẹ̀ kékeré gan-an, bíi rírìn fún ìṣẹ́jú 5.', 'Fi kún un díẹ̀díẹ̀ kí o sì ṣètò ìsinmi. Ara lè máa dùn díẹ̀ ní ìbẹ̀rẹ̀.']::text[], null, null, 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('ed-3min', 'en', array['Pain that lasts more than 3 months often involves a sensitive nervous system.', 'Tissues have usually healed, but the alarm stays on.', 'Gradual movement and confidence help turn the alarm down.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('ed-arthritis', 'en', array['Exercise is safe and helpful for arthritis.', 'Strong muscles support and protect the joints.', 'Start gently and build up. Some aching after exercise is normal.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('ed-ces', 'en', array['A rare but serious back problem that needs emergency treatment.', 'Warning signs: numbness in the saddle area, new bladder or bowel problems, sexual problems, leg weakness.', 'If these appear, go to the emergency department straight away.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('ed-clch', 'en', array['An NHS video explaining how pain works.', 'Pain is influenced by thoughts, feelings, sleep and stress, not only the body.', 'Understanding this helps you take back control.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('ed-desk', 'en', array['Follow this 10-minute seated stretch routine at your desk.', 'It includes neck, shoulder and back stretches.', 'Get up and move every 30 to 60 minutes.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('ed-flare', 'en', array['Flare-ups are common and usually settle. They do not mean new damage.', 'Have a plan ready: reduce activity, but do not stop moving completely.', 'Use comfort measures such as heat, relaxation and gentle movement.', 'Return gradually to your usual activities over a few days.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('ed-flare', 'ha', array['Tashin ciwo abu ne da aka saba, kuma yawanci yana lafawa. Ba yana nufin sabon lalacewa ba.', 'Ka kasance da shiri: rage aiki, amma kada ka daina motsi gaba ɗaya.', 'Yi amfani da abubuwan jin daɗi kamar zafi, shakatawa, da motsi a hankali.', 'Ka koma ayyukanka a hankali cikin ''yan kwanaki.']::text[], null, null, 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('ed-flare', 'ig', array['Mgbe mgbu na-abawanye bụ ihe a na-ahụkarị, ọ na-akwụsịkwa. Ọ pụtaghị mmebi ọhụrụ.', 'Nwee atụmatụ dị njikere: belata ọrụ, mana akwụsịla ịgagharị kpamkpam.', 'Jiri ihe na-eme ka ahụ dị gị mma dị ka ọkụ, izu ike, na mmegharị dị nro.', 'Jiri nwayọ laghachi n''ọrụ gị n''ime ụbọchị ole na ole.']::text[], null, null, 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('ed-flare', 'yo', array['Ìrora tí ó gbóná sí i wọ́pọ̀, ó sì máa ń rọlẹ̀. Kò túmọ̀ sí ìbàjẹ́ tuntun.', 'Ní ètò kan sílẹ̀: dín iṣẹ́ kù, ṣùgbọ́n má ṣe dáwọ́ gbígbéra dúró pátápátá.', 'Lo ohun ìtùnú bíi ooru, ìsinmi-ọkàn, àti gbígbéra jẹ́jẹ́.', 'Padà sí iṣẹ́ rẹ díẹ̀díẹ̀ láàárín ọjọ́ díẹ̀.']::text[], null, null, 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('ed-mri', 'en', array['Many people without pain have disc bulges and wear on their scans.', 'These changes are often normal with age, like grey hair.', 'Scans are needed only when red flags are present or surgery is being considered.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('ed-pacing-nhs', 'en', array['An NHS pain team explains how to set a baseline for activities.', 'Plan your day with a balance of activity and rest.', 'Build up gradually, even when you feel good.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('ed-pacing', 'en', array['Avoid the boom-and-bust pattern: doing too much on good days and crashing after.', 'Find a starting amount of activity you can do even on a bad day.', 'Break tasks into smaller parts with planned rests.', 'Increase slowly, by about 10 percent each week.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('ed-pacing', 'ha', array['Ka guji yin aiki da yawa a ranaku masu kyau sannan ka faɗi daga baya.', 'Nemo yawan aikin da za ka iya yi ko a ranar da ba ta da kyau.', 'Raba ayyuka zuwa ƙananan sassa tare da hutun da aka tsara.', 'Ka ƙara a hankali, kusan kashi 10 cikin 100 a kowane mako.']::text[], null, null, 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('ed-pacing', 'ig', array['Zere ime ihe karịrị akarị n''ụbọchị dị mma, wee daa mgbe nke ahụ gasịrị.', 'Chọta ọnụọgụ ọrụ ị nwere ike ime ọbụlagodi n''ụbọchị ọjọọ.', 'Kewaa ọrụ n''obere akụkụ, were ezumike a haziri ahazi.', 'Na-agbakwunye nwayọ nwayọ, ihe dị ka pasentị 10 kwa izu.']::text[], null, null, 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('ed-pacing', 'yo', array['Yẹra fún ṣíṣe púpọ̀ jù ní ọjọ́ dáradára kí o sì ṣubú lẹ́yìn rẹ̀.', 'Wá ìwọ̀n iṣẹ́ tí o lè ṣe kódà ní ọjọ́ burúkú.', 'Pín iṣẹ́ sí apá kékeré pẹ̀lú ìsinmi tí a ti ṣètò.', 'Fi kún un díẹ̀díẹ̀, bíi ìdá mẹ́wàá nínú ọgọ́rùn-ún ní ọ̀sẹ̀ kọ̀ọ̀kan.']::text[], null, null, 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('ed-posture', 'en', array['There is no single correct posture.', 'The best posture is the next one: change position often.', 'Slouching is not dangerous. Staying still for too long is what causes stiffness.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('ed-redflags', 'en', array['Explains the rare warning signs that need urgent medical help.', 'These include numbness around the bottom, bladder or bowel problems, fever, or unexplained weight loss.', 'If you notice any of these, go to the nearest emergency department or call 112.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('ed-sleep-hss', 'en', array['Explains the two-way link between pain and sleep.', 'Simple sleep habits can reduce pain over time.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('ed-sleep', 'en', array['Poor sleep makes pain worse, and pain makes sleep worse.', 'Keep regular sleep and wake times.', 'Limit screens, caffeine and heavy meals before bed.', 'A calm bedtime routine helps your body wind down.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('ed-sleep', 'ha', array['Rashin barci mai kyau yana ƙara ciwo, ciwo kuma yana hana barci.', 'Ka riƙa kwanciya da tashi a lokaci ɗaya kowace rana.', 'Ka rage waya, kofi, da abinci mai nauyi kafin barci.', 'Al''adar natsuwa kafin barci tana taimaka wa jiki ya huta.']::text[], null, null, 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('ed-sleep', 'ig', array['Ụra na-adịghị mma na-eme ka mgbu ka njọ, mgbu na-emekwa ka ụra ka njọ.', 'Na-ehi ụra ma na-eteta n''otu oge kwa ụbọchị.', 'Belata ekwentị, kọfị, na nri dị arọ tupu ị lakpuo ụra.', 'Omume dị jụụ tupu ụra na-enyere ahụ aka izu ike.']::text[], null, null, 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('ed-sleep', 'yo', array['Oorun tí kò dára máa ń mú ìrora burú sí i, ìrora náà sì máa ń ba oorun jẹ́.', 'Máa sùn kí o sì jí ní àkókò kan náà lójoojúmọ́.', 'Dín fóònù, kọfí, àti oúnjẹ wúwo kù kí o tó sùn.', 'Ìṣe ìfọkànbalẹ̀ kí o tó sùn ń ran ara lọ́wọ́ láti sinmi.']::text[], null, null, 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('ed-stress', 'en', array['Stress puts the body on alert, which can make pain feel stronger.', 'Relaxed breathing, enough sleep and regular movement calm the system.', 'Managing stress is part of managing pain.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('ed-stress', 'ha', array['Damuwa tana sa jiki cikin faɗaka, wanda zai iya sa ciwo ya fi ƙarfi.', 'Numfashi a hankali, isasshen barci, da motsi akai-akai suna kwantar da jiki.', 'Sarrafa damuwa wani ɓangare ne na sarrafa ciwo.']::text[], null, null, 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('ed-stress', 'ig', array['Nchekasị na-eme ka ahụ nọrọ na nche, nke nwere ike ime ka mgbu sie ike.', 'Iku ume nwayọ, ụra zuru oke, na mmegharị ahụ mgbe niile na-eme ka ahụ dajụọ.', 'Ijikwa nchekasị bụ akụkụ nke ijikwa mgbu.']::text[], null, null, 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('ed-stress', 'yo', array['Ìdààmú máa ń fi ara sí ipò ìṣọ́ra, èyí sì lè mú kí ìrora le sí i.', 'Mími jẹ́jẹ́, oorun tó pé, àti gbígbéra déédéé ń mú ara balẹ̀.', 'Ṣíṣàkóso ìdààmú jẹ́ apá kan ṣíṣàkóso ìrora.']::text[], null, null, 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('ed-tame', 'en', array['Persistent pain is like a protective beast that has grown too big.', 'Pain is made by the brain and nervous system to protect you, not a direct measure of damage.', 'Learning about pain, moving, and doing things you value can retrain the system.', 'Recovery is possible, step by step.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('ed-tame', 'ha', array['Ciwo mai daɗewa kamar dabba ce mai kariya da ta yi girma fiye da kima.', 'Ƙwaƙwalwa da tsarin jijiyoyi ne ke samar da ciwo don kare ka, ba ma''aunin lalacewa kai tsaye ba.', 'Koyon game da ciwo, motsi, da yin abubuwan da kake so na iya sake horar da tsarin.', 'Warkewa mai yiwuwa ne, mataki-mataki.']::text[], null, null, 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('ed-tame', 'ig', array['Mgbu na-adịte aka dị ka anụ na-echekwa gị nke tolitere karịa.', 'Ụbụrụ na akwara ozi na-emepụta mgbu iji chebe gị, ọ bụghị ọ̀tụ̀tụ̀ mmebi kpọmkwem.', 'Ịmụta maka mgbu, ịgagharị, na ime ihe ị hụrụ n''anya nwere ike ịzụgharị usoro ahụ.', 'Ịgbake ga-ekwe omume, nzọụkwụ na nzọụkwụ.']::text[], null, null, 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('ed-tame', 'yo', array['Ìrora tí ó pẹ́ dà bí ẹranko olùdáàbòbò tí ó ti dàgbà jù.', 'Ọpọlọ àti ètò iṣan-ara ló ń dá ìrora láti dáàbò bò ọ́, kì í ṣe ìwọ̀n ìbàjẹ́ tààrà.', 'Kíkọ́ nípa ìrora, gbígbéra, àti ṣíṣe àwọn nǹkan tí o fẹ́ràn lè tún ètò náà kọ́.', 'Ìmúláradá ṣeé ṣe, ní ìgbésẹ̀ kọ̀ọ̀kan.']::text[], null, null, 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('ed-tendon', 'en', array['Tendons get stronger when they are loaded gradually.', 'Complete rest weakens a tendon; too much too soon irritates it.', 'Mild pain during exercise that settles by the next day is usually OK.', 'Tendon recovery often takes 3 months or more.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('ed-understand', 'en', array['Pain is the body''s alarm system. It is real, but it does not always mean damage.', 'With long-lasting pain, the alarm can become too sensitive.', 'Movement, sleep, managing stress and gradual activity can calm the alarm down.', 'Small steps, done regularly, help most.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('ed-understand', 'ha', array['Ciwo shi ne ƙararrawar faɗakarwa ta jiki. Gaskiya ne, amma ba koyaushe yake nufin lalacewa ba.', 'Idan ciwo ya daɗe, ƙararrawar na iya zama mai saurin kaɗawa.', 'Motsi, barci, sarrafa damuwa, da yin abubuwa sannu a hankali na iya kwantar da ƙararrawar.', 'Ƙananan matakai, da ake yi akai-akai, su ne suka fi taimakawa.']::text[], null, null, 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('ed-understand', 'ig', array['Mgbu bụ mgbịrịgba ịdọ aka na ntị nke ahụ. Ọ bụ eziokwu, mana ọ naghị egosi mgbe niile na ihe mebiri emebi.', 'Mgbe mgbu dịtere aka, mgbịrịgba ahụ nwere ike ịdị ngwa ngwa ịkụ.', 'Mmegharị ahụ, ụra, ijikwa nchekasị, na ime ihe nke nta nke nta nwere ike ime ka mgbịrịgba ahụ dajụọ.', 'Obere nzọụkwụ, a na-eme mgbe niile, na-enyere aka kachasị.']::text[], null, null, 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('ed-understand', 'yo', array['Ìrora ni agogo-ìkìlọ̀ ara. Ó jẹ́ òótọ́, ṣùgbọ́n kì í ṣe ìgbà gbogbo ni ó túmọ̀ sí ìbàjẹ́.', 'Nígbà tí ìrora bá pẹ́, agogo náà lè di èyí tí ó ń tètè dún jù.', 'Gbígbéra, oorun, ìṣàkóso ìdààmú, àti ṣíṣe nǹkan díẹ̀díẹ̀ lè mú kí agogo náà rọlẹ̀.', 'Ìgbésẹ̀ kékeré tí a ń ṣe déédéé ló ń ranni lọ́wọ́ jùlọ.']::text[], null, null, 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('el-aaa-golf', 'en', array['NHS web page explaining golfer''s elbow with a staged exercise programme.', 'Start with static holds and move on when they are comfortable.', 'Gradually return to gripping and lifting.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('el-aaa-tennis', 'en', array['NHS web page with static, strengthening and grip exercises for tennis elbow, each with a video.', 'Start with static holds, then move on to strengthening.', 'Recovery often takes several months of regular exercise.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('el-cubital', 'en', array['Explains why the ulnar nerve at the elbow causes tingling in the ring and little fingers.', 'Avoid leaning on the elbow and keeping it fully bent for long periods, especially at night.', 'Explains treatment options and when surgery is considered.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('el-distal-biceps', 'en', array['Printable programme from gentle elbow movement and stretches to strengthening.', 'Start with the early movement and static exercises.', 'Your specialist will tell you when to progress to weights.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('el-ecc-band', 'en', array['Sit with your forearm supported, palm down, holding a band or light weight.', 'Lift the wrist up using your other hand to help.', 'Lower it slowly on its own.', 'Do 3 sets of 15 once a day.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('el-ecc', 'en', array['Rest your forearm on a table, palm down, holding a light weight or water bottle.', 'Use your other hand to help lift the wrist up.', 'Slowly lower the weight down on your own over 3 to 5 seconds.', 'Do 15 repetitions, building to 3 sets of 15.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('el-golf-air', 'en', array['Stretch: straighten your arm with palm up and gently pull the fingers back with the other hand. Hold 30 seconds.', 'Strengthen: rest your forearm palm-up and curl a light weight up, then lower slowly.', 'Keep all movements slow and pain no more than mild.', 'Do 10 to 15 repetitions, once or twice a day.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('el-golf-band', 'en', array['Stand on one end of a resistance band and hold the other end with your palm facing up.', 'Curl your wrist up against the band, then lower slowly.', 'Keep your elbow still by your side.', 'Do 3 sets of 15.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('el-golf-bb', 'en', array['Rest your forearm on a table with the palm facing up.', 'Slowly curl the wrist up while holding a light weight, then lower slowly.', 'Keep the elbow still.', 'Do 3 sets of 10 to 15.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('el-iso', 'en', array['Sit with your forearm resting on a table, palm facing down, hand over the edge.', 'Place your other hand on the back of the hand and push up into it without moving.', 'Hold 10 seconds in week 1, building to 40 seconds by week 4.', 'Repeat 5 times, 4 times a day.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('el-towel', 'en', array['Hold a rolled towel in both hands in front of you.', 'Twist it as if wringing out water, one way and then the other.', 'Keep the movement slow and controlled.', 'Do 15 repetitions, building to 3 sets of 15.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('hp-aaa-gt', 'en', array['NHS web page with staged exercises and videos for pain on the outside of the hip.', 'Includes advice on sleeping positions and daily activities.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('hp-aaa-oa', 'en', array['NHS web page with four stages of hip exercises, each with a video.', 'Exercise is one of the best treatments for hip osteoarthritis.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('hp-bridge', 'en', array['Lie on your back with knees bent and feet flat, hip-width apart.', 'Lift your hips and hold for 5 seconds.', 'Lower slowly.', 'Start with 15, building to 3 sets of 15.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('hp-chairsquat', 'en', array['Stand in front of a chair with feet hip-width apart.', 'Push your hips back and bend your knees to lightly touch the chair.', 'Stand back up without using your hands if possible.', 'Do 3 sets of 15.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('hp-gt-esht', 'en', array['NHS leaflet: static hip push-out, bridges, single-leg bridges, squats, side-walks and lunges.', 'Avoid crossing your legs and standing hanging on one hip.', 'Progress through the stages as pain allows.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('hp-hamstring', 'en', array['Printable staged programme for a hamstring strain.', 'Moves from gentle activation to strengthening, running and return to sport.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('hp-iliopsoas', 'en', array['Start with gentle hip flexor stretches in a half-kneeling position.', 'Add strengthening by lifting the knee up slowly while standing or lying.', 'Progress resistance only if pain stays mild.', 'Do 8 to 12 repetitions of each.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('hp-iso-lying', 'en', array['Lie on your back with a belt or band around your knees.', 'Press your knees gently outwards into the band without moving.', 'Hold 10 seconds in week 1, building to 40 seconds by week 4.', 'Repeat 5 times, 4 times a day.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('hp-pelvic-dip', 'en', array['Stand side-on on the bottom step, holding the rail, on the painful leg.', 'Let the other hip drop down slowly, keeping the standing knee straight.', 'Lift it back up using the muscles at the side of the standing hip.', 'Start with 15, building to 3 sets of 15.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('hp-prox-ham', 'en', array['Avoid long sitting on hard surfaces and deep hamstring stretches early on.', 'Start with static holds such as a bridge hold with knees bent.', 'Progress to bridges, hip hinges and then running drills over weeks.', 'Follow the dose your specialist sets.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('hp-sideabd', 'en', array['Lie on your side with the bottom knee bent and the top leg straight.', 'Lift the top leg up slowly, keeping it slightly behind you and your toes pointing forwards.', 'Lower slowly.', 'Do 3 sets of 15.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('hp-squeeze', 'en', array['Lie on your back with your legs straight.', 'Squeeze your buttocks together and hold for 5 seconds.', 'Relax fully.', 'Do 3 sets of 15.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('hp-swing', 'en', array['Stand on a step or a thick book holding a support, with one leg hanging free.', 'Let the free leg swing gently forwards and back.', 'Keep it relaxed. Do not force the movement.', 'Do 30 swings, 3 times a day.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('hp-thr-adv', 'en', array['Start these only when your team says you are ready.', 'Follow the video for standing strengthening and balance exercises.', 'Use a support to hold on to.', 'Do 10 repetitions of each, once or twice a day.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('hp-thr-lie', 'en', array['Lie on your back on the bed.', 'Follow the video: ankle pumps, buttock squeezes, thigh tightening and sliding the leg out and back.', 'Keep within your hip precautions.', 'Do 10 repetitions of each, 3 to 4 times a day.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('hp-thr-stand', 'en', array['Stand holding a firm support such as a kitchen worktop.', 'Follow the video: lift the knee, move the leg out to the side and back, keeping your body upright.', 'Move slowly and keep within the precautions your surgical team gave you.', 'Do 10 repetitions of each, 3 times a day.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('hp-ucsf', 'en', array['Printable programme of progressive hip strengthening.', 'Start with the early-phase exercises and progress as advised.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('kn-aaa-oa', 'en', array['NHS web page with stretching and strengthening videos for knee osteoarthritis.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('kn-aaa-pfps', 'en', array['NHS web page with stretching and strengthening videos for front-of-knee pain.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('kn-aaa-tendon', 'en', array['NHS web page with five levels of static exercises, then strengthening and jumping, each with a video.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('kn-aaa-tkr', 'en', array['NHS web page about preparing for and recovering from a knee replacement.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('kn-band-onnit', 'en', array['Follow the five band exercises for the hips and knees.', 'Keep the knee in line with your toes in every movement.', 'Move slowly and with control.', 'Do 10 to 15 repetitions of each.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('kn-band-short', 'en', array['Loop a resistance band as shown in the video.', 'Straighten or push the knee against the band slowly.', 'Return slowly with control.', 'Do 10 to 15 repetitions, 2 to 3 sets.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('kn-calf-st', 'en', array['Stand facing a wall with one foot in front of the other.', 'Keep the back heel down and the back knee straight, lean forwards. Hold 30 seconds.', 'Then bend the back knee slightly to stretch lower down. Hold 30 seconds.', 'Repeat 5 times.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('kn-decline', 'en', array['Stand on a slope or decline board on one leg, holding a support.', 'Slowly bend the knee to lower down.', 'Use both legs to push back up.', 'Do 3 sets of 15 when your specialist says you are ready.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('kn-ham-wall', 'en', array['Lie on your back near a doorway or wall.', 'Rest one leg straight up the wall with the other leg flat on the floor.', 'Move closer to the wall to increase the stretch at the back of the thigh.', 'Hold 30 seconds, repeat 5 times.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('kn-ham-wall', 'ha', array['Kwanta a bayanka kusa da bango ko ƙofa.', 'Ka ɗora ƙafa ɗaya a miƙe sama a jikin bango, ɗayan a ƙasa.', 'Ka matso kusa da bango don ƙara miƙewa a bayan cinya.', 'Riƙe na daƙiƙa 30, sau 5.']::text[], null, null, 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('kn-ham-wall', 'ig', array['Dinara n''azụ gị n''akụkụ mgbidi ma ọ bụ ọnụ ụzọ.', 'Dabere otu ụkwụ kwụ ọtọ n''elu mgbidi, ụkwụ nke ọzọ n''ala.', 'Bịaruo mgbidi nso iji mee ka ọgbatị n''azụ apata dịkwuo.', 'Jide ya sekọnd 30, mee ya ugboro 5.']::text[], null, null, 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('kn-ham-wall', 'yo', array['Dùbúlẹ̀ lórí ẹ̀yìn rẹ nítòsí ògiri tàbí ẹnu ọ̀nà.', 'Gbé ẹsẹ̀ kan tààrà sókè sí ògiri, kí ẹsẹ̀ kejì wà lórí ilẹ̀.', 'Súnmọ́ ògiri síi láti mú ìfàsẹ́yìn pọ̀ sí i lẹ́yìn itan.', 'Dì í mú fún ìṣẹ́jú-àáyá 30, ní ìgbà 5.']::text[], null, null, 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('kn-menisc-ham', 'en', array['Sit or lie with one leg straight.', 'Lean forwards from your hips, or lift the straight leg, until you feel a stretch behind the thigh.', 'Keep your back straight.', 'Hold 30 seconds, repeat 3 times, 4 times a day.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('kn-menisc', 'en', array['Start with thigh tightening and straight leg raises.', 'Add bridges, side-lying leg lifts and gentle mini squats.', 'Avoid deep squats and twisting on a bent knee early on.', 'Do 10 to 15 repetitions of each, once a day.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('kn-minisquat', 'en', array['Stand with feet hip-width apart, holding a support if needed.', 'Bend your knees a little as if starting to sit down.', 'Keep your knees over your toes and your back straight. Stand back up.', 'Start with 15 daily, building to 3 sets of 15.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('kn-minisquat', 'ha', array['Tsaya ƙafafunka a buɗe daidai da kugu, ka riƙe wani abu idan ya cancanta.', 'Ka ɗan lanƙwasa gwiwoyinka kamar za ka fara zama.', 'Gwiwoyinka su kasance a saman yatsun ƙafa, bayanka a miƙe. Ka tashi.', 'Fara da 15 a rana, har zuwa zagaye uku na 15.']::text[], null, null, 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('kn-minisquat', 'ig', array['Guzoro, ụkwụ gị gbasaa dị ka úkwù, jide ihe ma ọ dị mkpa.', 'Hulata ikpere gị ntakịrị dị ka ị na-amalite ịnọdụ ala.', 'Mee ka ikpere gị dị n''elu mkpịsị ụkwụ gị, azụ gị kwụ ọtọ. Bilie ọzọ.', 'Malite na 15 kwa ụbọchị, ruo usoro atọ nke 15.']::text[], null, null, 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('kn-minisquat', 'yo', array['Dúró kí ẹsẹ̀ rẹ jìnnà síra bí ìbàdí, di nǹkan mú bí ó bá yẹ.', 'Tẹ orúnkún rẹ díẹ̀ bí ẹni tí ó fẹ́ jókòó.', 'Jẹ́ kí orúnkún rẹ wà lókè ìka ẹsẹ̀ rẹ, kí ẹ̀yìn rẹ tọ́. Dìde padà.', 'Bẹ̀rẹ̀ pẹ̀lú 15 lójúmọ́, títí dé ìpele mẹ́ta ti 15.']::text[], null, null, 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('kn-pfps-ober', 'en', array['Printable programme: stretches for hamstring, thigh, hip flexor and calf, plus hip and thigh strengthening.', 'Includes step-downs, wall squat hold and clams.', 'Usually continued for about 6 weeks.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('kn-pfps1', 'en', array['Start with gentle exercises such as thigh tightening, straight leg raises and side-lying hip lifts.', 'Move slowly and keep pain low.', 'Rest between sets.', 'Do 10 to 15 repetitions, 2 to 3 sets, once a day.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('kn-pfps1', 'ha', array['Fara da motsa jiki a hankali kamar matse tsokar cinya, ɗaga ƙafa a miƙe, da ɗaga ƙafa ta gefe.', 'Yi a hankali, ciwo ya kasance kaɗan.', 'Ka huta tsakanin zagaye.', 'Yi sau 10 zuwa 15, zagaye 2 zuwa 3, sau ɗaya a rana.']::text[], null, null, 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('kn-pfps1', 'ig', array['Malite na mmega dị nro dị ka ịpịkọ akwara apata, ibuli ụkwụ kwụ ọtọ, na ibuli ụkwụ n''akụkụ.', 'Jiri nwayọ mee ya, mee ka mgbu dị ala.', 'Zuru ike n''etiti usoro.', 'Mee ya ugboro 10 ruo 15, usoro 2 ruo 3, otu ugboro kwa ụbọchị.']::text[], null, null, 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('kn-pfps1', 'yo', array['Bẹ̀rẹ̀ pẹ̀lú eré-ìdárayá jẹ́jẹ́ bíi fífún iṣan itan, gbígbé ẹsẹ̀ tààrà sókè, àti gbígbé ẹsẹ̀ sókè ní ẹ̀gbẹ́.', 'Rọra ṣe é kí ìrora wà ní ìsàlẹ̀.', 'Sinmi láàárín ìpele kọ̀ọ̀kan.', 'Ṣe é ní ìgbà 10 sí 15, ìpele 2 sí 3, lẹ́ẹ̀kan lójúmọ́.']::text[], null, null, 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('kn-pfps2', 'en', array['Move on to this phase when phase 1 is easy.', 'Exercises include squats, step-ups and bridges.', 'Keep your knee in line with your toes.', 'Do 10 to 15 repetitions, 2 to 3 sets, once a day.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('kn-quad-st', 'en', array['Stand holding a support.', 'Bend one knee and hold your ankle behind you, or use a towel around the ankle.', 'Keep your knees together and stand tall until you feel a stretch in the front of the thigh.', 'Hold 30 seconds, repeat 5 times.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('kn-quad-st', 'ha', array['Tsaya kana riƙe da wani abu.', 'Ka lanƙwasa gwiwa ɗaya ka riƙe idon sawunka a baya, ko ka yi amfani da tawul.', 'Gwiwoyinka su kasance tare, ka tsaya a miƙe har ka ji miƙewa a gaban cinya.', 'Riƙe na daƙiƙa 30, sau 5.']::text[], null, null, 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('kn-quad-st', 'ig', array['Guzoro, jide ihe ị ga-adabere.', 'Hulata otu ikpere, jide nkwonkwo ụkwụ gị n''azụ, ma ọ bụ jiri akwa nhicha kee ya.', 'Mee ka ikpere abụọ dị nso, guzoro ọtọ ruo mgbe ị nwere ọgbatị n''ihu apata.', 'Jide ya sekọnd 30, mee ya ugboro 5.']::text[], null, null, 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('kn-quad-st', 'yo', array['Dúró kí o di nǹkan mú.', 'Tẹ orúnkún kan kí o mú kókósẹ̀ rẹ lẹ́yìn, tàbí lo aṣọ ìnura yí kókósẹ̀ ká.', 'Jẹ́ kí orúnkún méjèèjì wà papọ̀, dúró ṣánṣán títí o fi ní ìfàsẹ́yìn ní iwájú itan.', 'Dì í mú fún ìṣẹ́jú-àáyá 30, ní ìgbà 5.']::text[], null, null, 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('kn-quadset', 'en', array['Sit with your leg straight out on a bed or a chair.', 'Tighten your thigh muscle to push the back of the knee down.', 'Hold 45 seconds, rest 2 minutes.', 'Repeat 5 times, 3 times a day.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('kn-racgp', 'en', array['Printable set of knee strengthening exercises for osteoarthritis.', 'Regular strengthening reduces pain and improves function.', 'Aim for most days of the week.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('kn-stepup', 'en', array['Stand facing the bottom step. Hold the rail if needed.', 'Step up with one foot and push through that leg to stand on the step.', 'Step down slowly with control.', 'Start with 15 daily, building to 3 sets of 15.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('kn-stepup', 'ha', array['Tsaya kana fuskantar matakin ƙasa. Riƙe ƙarfen hannu idan ya cancanta.', 'Taka sama da ƙafa ɗaya ka tura da wannan ƙafar har ka tsaya a kan matakin.', 'Ka sauko a hankali.', 'Fara da 15 a rana, har zuwa zagaye uku na 15.']::text[], null, null, 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('kn-stepup', 'ig', array['Guzoro chere ihu n''steepụ nke ala. Jide osisi aka ma ọ dị mkpa.', 'Were otu ụkwụ rịgoro, kwagharịa site n''ụkwụ ahụ ka ị guzoro n''elu steepụ.', 'Jiri nwayọ rịdata.', 'Malite na 15 kwa ụbọchị, ruo usoro atọ nke 15.']::text[], null, null, 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('kn-stepup', 'yo', array['Dúró kí o kọjú sí àtẹ̀gùn ìsàlẹ̀. Di ọ̀pá mú bí ó bá yẹ.', 'Gbé ẹsẹ̀ kan sórí àtẹ̀gùn kí o fi ẹsẹ̀ yẹn tì ara rẹ sókè láti dúró lórí rẹ̀.', 'Sọ̀ kalẹ̀ jẹ́jẹ́ pẹ̀lú ìkáwọ́.', 'Bẹ̀rẹ̀ pẹ̀lú 15 lójúmọ́, títí dé ìpele mẹ́ta ti 15.']::text[], null, null, 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('kn-sts', 'en', array['Sit on a firm chair with feet flat.', 'Stand up, leaning forwards slightly, without using your hands if you can.', 'Sit down slowly.', 'Start with 15 daily, building to 3 sets of 15.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('kn-sts', 'ha', array['Zauna a kan kujera mai ƙarfi, ƙafafunka a ƙasa.', 'Ka tashi, kana ɗan sunkuyawa gaba, ba tare da hannu ba idan za ka iya.', 'Ka zauna a hankali.', 'Fara da 15 a rana, har zuwa zagaye uku na 15.']::text[], null, null, 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('kn-sts', 'ig', array['Nọdụ n''oche siri ike, ụkwụ gị n''ala.', 'Bilie, hulata n''ihu ntakịrị, n''ejighị aka gị ma ị nwere ike.', 'Jiri nwayọ nọdụ ala.', 'Malite na 15 kwa ụbọchị, ruo usoro atọ nke 15.']::text[], null, null, 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('kn-sts', 'yo', array['Jókòó lórí àga tó le, kí àtẹ́lẹsẹ̀ rẹ wà lórí ilẹ̀.', 'Dìde, kí o tẹ̀ síwájú díẹ̀, láìlo ọwọ́ rẹ bí o bá lè ṣe é.', 'Jókòó padà jẹ́jẹ́.', 'Bẹ̀rẹ̀ pẹ̀lú 15 lójúmọ́, títí dé ìpele mẹ́ta ti 15.']::text[], null, null, 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('kn-tendon', 'en', array['Start with static holds such as a wall sit or a static leg extension to ease pain.', 'Progress to slow, heavy strengthening such as split squats.', 'Later add spring-like movements such as hopping when your specialist advises.', 'Pain up to 3 out of 10 during exercise is usually acceptable.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('kn-tkr', 'en', array['Lie on the bed. Pump your ankles up and down.', 'Tighten your thigh to push the knee down, and hold.', 'Bend and straighten the knee by sliding your heel along the bed.', 'Do 10 repetitions of each, 3 to 4 times a day.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('kn-wallsit', 'en', array['Lean your back against a wall and slide down to a comfortable bend in the knees.', 'Hold the position.', 'Hold 45 seconds, rest 2 minutes.', 'Repeat 5 times, 3 times a day.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('kn-wallsquat', 'en', array['Stand with your back against a wall and feet a step away from it.', 'Slide down the wall by bending your knees a little.', 'Keep your knees in line with your toes. Slide back up.', 'Start with 15 daily, building to 3 sets of 15.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('kn-wallsquat', 'ha', array['Tsaya bayanka a jingine da bango, ƙafafunka taku ɗaya daga bango.', 'Ka zame ƙasa a kan bango ta hanyar ɗan lanƙwasa gwiwoyinka.', 'Gwiwoyinka su kasance daidai da yatsun ƙafa. Ka zame sama.', 'Fara da 15 a rana, har zuwa zagaye uku na 15.']::text[], null, null, 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('kn-wallsquat', 'ig', array['Guzoro, azụ gị dabere na mgbidi, ụkwụ gị dị otu nzọụkwụ site na mgbidi.', 'Jiri nwayọ rịdata na mgbidi site n''ihulata ikpere gị ntakịrị.', 'Mee ka ikpere gị kwụ n''ahịrị mkpịsị ụkwụ gị. Rịgoro azụ.', 'Malite na 15 kwa ụbọchị, ruo usoro atọ nke 15.']::text[], null, null, 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('kn-wallsquat', 'yo', array['Dúró kí ẹ̀yìn rẹ fara ti ògiri, kí ẹsẹ̀ rẹ jìnnà sí ògiri ní ìgbésẹ̀ kan.', 'Rọra sọ̀ kalẹ̀ lórí ògiri nípa títẹ orúnkún rẹ díẹ̀.', 'Jẹ́ kí orúnkún rẹ wà ní ìlà kan pẹ̀lú ìka ẹsẹ̀ rẹ. Gòkè padà.', 'Bẹ̀rẹ̀ pẹ̀lú 15 lójúmọ́, títí dé ìpele mẹ́ta ti 15.']::text[], null, null, 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('lb-aaa-stenosis', 'en', array['NHS web page explaining lumbar spinal stenosis and leg pain when walking.', 'Bending forwards or sitting often eases symptoms.', 'Regular walking in short bouts with rests is encouraged.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('lb-aaa', 'en', array['NHS web page with mobility, strengthening and nerve-gliding exercises, each with a video.', 'Start with section 1 when pain is high and add section 2 as you improve.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('lb-bridge', 'en', array['Lie on your back with your knees bent and feet flat.', 'Squeeze your buttocks and lift your hips until your body is in a straight line.', 'Hold briefly, then lower slowly.', 'Start with 15, building to 3 sets of 15.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('lb-bridge', 'ha', array['Kwanta a bayanka, gwiwoyinka a lanƙwashe, tafin ƙafafunka a ƙasa.', 'Ka matse ɗuwawunka ka ɗaga kwankwasonka har jikinka ya miƙe daidai.', 'Ka riƙe kaɗan, sannan ka sauko a hankali.', 'Fara da 15, har zuwa zagaye uku na 15.']::text[], null, null, 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('lb-bridge', 'ig', array['Dinara n''azụ gị, ikpere gị ehulata, ụkwụ gị n''ala.', 'Pịkọta ike gị ọnụ, bulie úkwù gị ruo mgbe ahụ gị kwụ ọtọ.', 'Jide ya nwa oge, wee jiri nwayọ wedata ya.', 'Malite na 15, ruo usoro atọ nke 15.']::text[], null, null, 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('lb-bridge', 'yo', array['Dùbúlẹ̀ lórí ẹ̀yìn rẹ, kí orúnkún rẹ tẹ̀, kí àtẹ́lẹsẹ̀ rẹ wà lórí ilẹ̀.', 'Fún ìdí rẹ papọ̀ kí o sì gbé ìbàdí rẹ sókè títí ara rẹ yóò fi tọ́.', 'Dì í mú díẹ̀, lẹ́yìn náà rọra sọ̀ kalẹ̀.', 'Bẹ̀rẹ̀ pẹ̀lú 15, títí dé ìpele mẹ́ta ti 15.']::text[], null, null, 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('lb-child', 'en', array['Kneel on the floor and sit back towards your heels.', 'Reach your arms forwards on the floor and let your head relax down.', 'Breathe slowly and feel a gentle stretch in your back.', 'Hold 10 seconds, repeat 5 times, 3 to 4 times a day.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('lb-child', 'ha', array['Durƙusa a ƙasa ka zauna baya zuwa dugaduganka.', 'Ka miƙa hannunka gaba a ƙasa, ka bar kanka ya sake ƙasa.', 'Ka yi numfashi a hankali, kana jin ɗan miƙewa a bayanka.', 'Riƙe na daƙiƙa 10, sau 5, sau uku zuwa huɗu a rana.']::text[], null, null, 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('lb-child', 'ig', array['Gbuo ikpere n''ala, nọdụ azụ gaa n''ikiri ụkwụ gị.', 'Setịpụ aka gị n''ihu n''ala, hapụ isi gị ka ọ dị jụụ n''ala.', 'Kuo ume nwayọ, ka ị nwee obere ọgbatị n''azụ gị.', 'Jide ya sekọnd 10, mee ya ugboro 5, ugboro atọ ruo anọ kwa ụbọchị.']::text[], null, null, 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('lb-child', 'yo', array['Kúnlẹ̀ lórí ilẹ̀ kí o sì jókòó sẹ́yìn sí gìgísẹ̀ rẹ.', 'Na apá rẹ síwájú lórí ilẹ̀ kí orí rẹ rọ̀ sílẹ̀.', 'Mí jẹ́jẹ́, kí o ní ìfàsẹ́yìn díẹ̀ ní ẹ̀yìn rẹ.', 'Dì í mú fún ìṣẹ́jú-àáyá 10, ní ìgbà 5, ní ìgbà mẹ́ta sí mẹ́rin lójúmọ́.']::text[], null, null, 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('lb-coccyx', 'en', array['Printable sheet of gentle stretches for tailbone pain.', 'A cushion with a cut-out can make sitting easier.', 'Do the stretches gently once or twice a day.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('lb-femoral', 'en', array['Lie on your side with the painful leg on top.', 'Hold the top ankle and gently bend the knee while moving the hip back.', 'Release and return. Keep it gentle and rhythmic.', 'Repeat for 30 seconds, a few times a day.']::text[], null, 'Stop if thigh pain or tingling increases and stays.', 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('lb-fwd-sit', 'en', array['Sit on a chair with your feet apart.', 'Slowly bend forwards, letting your hands slide down towards the floor.', 'Hold for 5 seconds, then slowly sit up.', 'Repeat 10 times, 3 to 4 times a day.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('lb-knee-roll', 'en', array['Lie on your back with your knees bent and feet flat.', 'Slowly let both knees roll to one side, keeping your shoulders on the floor.', 'Bring them back to the middle and roll to the other side.', 'Keep going gently for 60 seconds, 4 times a day.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('lb-knee-roll', 'ha', array['Kwanta a bayanka, gwiwoyinka a lanƙwashe, tafin ƙafafunka a ƙasa.', 'A hankali ka bar gwiwoyin biyu su faɗi gefe ɗaya, kafaɗunka a ƙasa.', 'Ka dawo da su tsakiya ka kai su ɗayan gefe.', 'Ka ci gaba a hankali na daƙiƙa 60, sau huɗu a rana.']::text[], null, null, 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('lb-knee-roll', 'ig', array['Dinara n''azụ gị, ikpere gị ehulata, ụkwụ gị n''ala.', 'Jiri nwayọ hapụ ikpere abụọ ka ha tụgharịa n''otu akụkụ, ubu gị nọrọ n''ala.', 'Weghachi ha n''etiti, wee tụgharịa ha n''akụkụ nke ọzọ.', 'Mee ya nwayọ nwayọ maka sekọnd 60, ugboro anọ kwa ụbọchị.']::text[], null, null, 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('lb-knee-roll', 'yo', array['Dùbúlẹ̀ lórí ẹ̀yìn rẹ, kí orúnkún rẹ tẹ̀, kí àtẹ́lẹsẹ̀ rẹ wà lórí ilẹ̀.', 'Rọra jẹ́ kí orúnkún méjèèjì yí sí ẹ̀gbẹ́ kan, kí èjìká rẹ wà lórí ilẹ̀.', 'Mú wọn padà sí àárín kí o sì yí wọn sí ẹ̀gbẹ́ kejì.', 'Máa ṣe é jẹ́jẹ́ fún ìṣẹ́jú-àáyá 60, ní ìgbà mẹ́rin lójúmọ́.']::text[], null, null, 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('lb-mckenzie-sci', 'en', array['Printable sheet of extension-based exercises for back pain that is worse bending forwards.', 'If pain moves back towards the spine and away from the leg, that is a good sign.', 'Stop if pain spreads further down the leg.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('lb-mckenzie-ucsf', 'en', array['Printable programme: pelvic tilts, bird-dog, low plank, superman, bridges and back extension progression.', 'Back extension starts lying on your front and progresses to press-ups.', 'Your specialist will tell you where to start.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('lb-nhs-stretch', 'en', array['Follow along with these simple NHS back stretches on the floor.', 'They include knee-to-chest, knee rolls and a gentle arch stretch.', 'Move slowly and hold each stretch while breathing normally.', 'Do them once or twice a day.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('lb-nhs-stretch', 'ha', array['Bi waɗannan miƙe-miƙen baya na NHS a ƙasa.', 'Sun haɗa da jawo gwiwa zuwa ƙirji, juya gwiwoyi, da miƙewar baya a hankali.', 'Yi a hankali, kana numfashi yayin da kake riƙewa.', 'Yi sau ɗaya ko sau biyu a rana.']::text[], null, null, 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('lb-nhs-stretch', 'ig', array['Soro ọgbatị azụ NHS ndị a n''ala.', 'Ha gụnyere ịdọta ikpere n''obi, ịtụgharị ikpere, na ọgbatị azụ nwayọ.', 'Jiri nwayọ mee ya, kuo ume nke ọma mgbe ị na-ejide ọgbatị.', 'Mee ya otu ugboro ma ọ bụ ugboro abụọ kwa ụbọchị.']::text[], null, null, 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('lb-nhs-stretch', 'yo', array['Tẹ̀lé àwọn ìfàsẹ́yìn ẹ̀yìn NHS yìí lórí ilẹ̀.', 'Wọ́n ní fífa orúnkún sí àyà, yíyí orúnkún, àti ìfàsẹ́yìn ẹ̀yìn jẹ́jẹ́.', 'Rọra ṣe é, kí o máa mí dáadáa nígbà tí o bá ń dì í mú.', 'Ṣe é lẹ́ẹ̀kan tàbí lẹ́ẹ̀mejì lójúmọ́.']::text[], null, null, 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('lb-nhs-treat', 'en', array['Most back pain gets better within a few weeks.', 'Stay as active as you can and keep doing daily activities.', 'Avoid long bed rest. Gentle exercise helps recovery.', 'Pain relief and heat can help you keep moving.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('lb-nhs-treat', 'ha', array['Yawancin ciwon baya yana warkewa cikin ''yan makonni.', 'Ka ci gaba da motsi yadda za ka iya, kana yin ayyukan yau da kullum.', 'Kada ka daɗe kana kwance a gado. Motsa jiki a hankali yana taimakawa.', 'Maganin ciwo da zafi na iya taimaka maka ka ci gaba da motsi.']::text[], null, null, 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('lb-nhs-treat', 'ig', array['Ọtụtụ mgbu azụ na-aka mma n''ime izu ole na ole.', 'Nọgide na-eme ihe dịka i nwere ike, na-arụ ọrụ ụbọchị gị.', 'Ezela ike n''ihe ndina ogologo oge. Mmega ahụ dị nro na-enyere aka.', 'Ọgwụ mgbu na ọkụ nwere ike inyere gị aka ịnọgide na-agagharị.']::text[], null, null, 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('lb-nhs-treat', 'yo', array['Ọ̀pọ̀lọpọ̀ ìrora ẹ̀yìn máa ń sàn láàárín ọ̀sẹ̀ díẹ̀.', 'Máa ṣiṣẹ́ bí o ti lè ṣe tó, kí o sì máa ṣe iṣẹ́ ojoojúmọ́ rẹ.', 'Má ṣe dùbúlẹ̀ sórí ibùsùn fún ìgbà pípẹ́. Eré-ìdárayá jẹ́jẹ́ ń ranni lọ́wọ́.', 'Oògùn ìrora àti ooru lè ràn ọ́ lọ́wọ́ láti máa gbéra.']::text[], null, null, 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('lb-pelvic-rock', 'en', array['Lie on your back with your knees bent and feet flat.', 'Gently flatten your lower back into the floor by tilting your pelvis.', 'Then gently arch your lower back a little.', 'Rock slowly between the two, 5 to 10 times, 3 times a day.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('lb-pelvic-rock', 'ha', array['Kwanta a bayanka, gwiwoyinka a lanƙwashe, tafin ƙafafunka a ƙasa.', 'A hankali ka manna ƙasan bayanka a ƙasa ta hanyar karkata kwankwasonka.', 'Sannan a hankali ka ɗaga ƙasan bayanka kaɗan.', 'Ka yi lilo a hankali tsakanin biyun, sau 5 zuwa 10, sau uku a rana.']::text[], null, null, 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('lb-pelvic-rock', 'ig', array['Dinara n''azụ gị, ikpere gị ehulata, ụkwụ gị n''ala.', 'Jiri nwayọ pịa ala azụ gị n''ala site n''ịtụgharị úkwù gị.', 'Wee jiri nwayọ bulie ala azụ gị ntakịrị.', 'Jiri nwayọ megharịa n''etiti ha abụọ, ugboro 5 ruo 10, ugboro atọ kwa ụbọchị.']::text[], null, null, 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('lb-pelvic-rock', 'yo', array['Dùbúlẹ̀ lórí ẹ̀yìn rẹ, kí orúnkún rẹ tẹ̀, kí àtẹ́lẹsẹ̀ rẹ wà lórí ilẹ̀.', 'Rọra tẹ ìsàlẹ̀ ẹ̀yìn rẹ mọ́ ilẹ̀ nípa yíyí ìbàdí rẹ.', 'Lẹ́yìn náà rọra gbé ìsàlẹ̀ ẹ̀yìn rẹ sókè díẹ̀.', 'Máa yí láàárín méjèèjì jẹ́jẹ́, ní ìgbà 5 sí 10, ní ìgbà mẹ́ta lójúmọ́.']::text[], null, null, 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('lb-sciatic-glide', 'en', array['Sit on a chair, slumped slightly.', 'Straighten one knee while you look up, then bend the knee as you look down.', 'Keep the movement smooth. Do not hold the stretch.', 'Do it for 30 seconds, several times a day.']::text[], null, 'Stop if leg pain, tingling or numbness increases and does not settle within a few minutes.', 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('lb-sciatic-glide', 'ha', array['Zauna a kan kujera, ka ɗan sunkuya.', 'Ka miƙe gwiwa ɗaya yayin da kake kallon sama, sannan ka lanƙwasa gwiwar yayin da kake kallon ƙasa.', 'Motsin ya kasance a santsi. Kada ka riƙe miƙewar.', 'Yi na daƙiƙa 30, sau da yawa a rana.']::text[], null, null, 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('lb-sciatic-glide', 'ig', array['Nọdụ n''oche, hulata ntakịrị.', 'Setịa otu ikpere ka ị na-ele elu, wee hulata ikpere ka ị na-ele ala.', 'Mee ka mmegharị ahụ dị nro. Ejidela ọgbatị ahụ.', 'Mee ya maka sekọnd 30, ọtụtụ ugboro kwa ụbọchị.']::text[], null, null, 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('lb-sciatic-glide', 'yo', array['Jókòó sórí àga, kí o tẹ̀ díẹ̀.', 'Na orúnkún kan tààrà bí o ṣe ń wo òkè, lẹ́yìn náà tẹ orúnkún bí o ṣe ń wo ilẹ̀.', 'Jẹ́ kí ìgbésẹ̀ náà rọ̀. Má ṣe dì í mú.', 'Ṣe é fún ìṣẹ́jú-àáyá 30, ní ọ̀pọ̀ ìgbà lójúmọ́.']::text[], null, null, 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('lb-sciatica-nhs', 'en', array['Sciatica is pain from an irritated nerve running down the leg.', 'It usually gets better in 4 to 6 weeks.', 'Keep moving, use pain relief and do gentle exercises.', 'Get urgent help if you have red-flag symptoms such as numbness around the bottom or bladder problems.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('lb-sit-rock', 'en', array['Sit on a firm chair with your feet flat.', 'Slowly roll your pelvis back so your lower back slumps a little.', 'Then roll forwards so you sit tall with a small arch.', 'Repeat 5 to 10 times, 3 times a day.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('lb-stenosis', 'en', array['Lie on your back and bring one or both knees towards your chest to gently round the lower back.', 'Then try a forward-leaning stretch in sitting.', 'These positions open the spaces for the nerves and often ease leg symptoms.', 'Hold 20 to 30 seconds, 3 to 5 times, once or twice a day.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('lb-sts', 'en', array['Sit near the front of a firm chair with feet hip-width apart.', 'Lean forwards slightly and stand up without using your hands if you can.', 'Sit back down slowly and with control.', 'Start with 15, building to 3 sets of 15.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('lb-sts', 'ha', array['Zauna a gaban kujera mai ƙarfi, ƙafafunka a buɗe daidai da kugu.', 'Ka ɗan sunkuya gaba ka tashi ba tare da amfani da hannu ba idan za ka iya.', 'Ka zauna baya a hankali.', 'Fara da 15, har zuwa zagaye uku na 15.']::text[], null, null, 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('lb-sts', 'ig', array['Nọdụ n''ihu oche siri ike, ụkwụ gị gbasaa dị ka úkwù.', 'Hulata n''ihu ntakịrị, bilie n''ejighị aka gị ma ọ bụrụ na ị nwere ike.', 'Jiri nwayọ nọdụ ala ọzọ.', 'Malite na 15, ruo usoro atọ nke 15.']::text[], null, null, 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('lb-sts', 'yo', array['Jókòó sí iwájú àga tó le, kí ẹsẹ̀ rẹ jìnnà síra wọn bí ìbàdí.', 'Tẹ̀ síwájú díẹ̀ kí o dìde láìlo ọwọ́ rẹ bí o bá lè ṣe é.', 'Jókòó padà jẹ́jẹ́ pẹ̀lú ìkáwọ́.', 'Bẹ̀rẹ̀ pẹ̀lú 15, títí dé ìpele mẹ́ta ti 15.']::text[], null, null, 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('nk-3stretch', 'en', array['Upper trapezius: tip your ear towards your shoulder and hold.', 'Levator scapulae: turn your nose towards your armpit, then gently look down.', 'Scalenes: tip your head back and away slightly while holding the collarbone down.', 'Hold each stretch 30 seconds, 2 to 3 times each side.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('nk-3stretch', 'ha', array['Tsokar saman kafaɗa: karkata kunnenka zuwa kafaɗarka ka riƙe.', 'Tsokar gefen wuya: juya hancinka zuwa hammatarka, sannan a hankali ka kalli ƙasa.', 'Tsokar gaban wuya: a hankali ka karkata kanka baya kaɗan da gefe, hannunka yana riƙe ƙashin wuya a ƙasa.', 'Riƙe kowace miƙewa na daƙiƙa 30, sau 2 zuwa 3 a kowane gefe.']::text[], null, null, 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('nk-3stretch', 'ig', array['Akwara elu ubu: hulata ntị gị n''ubu gị, jide ya.', 'Akwara akụkụ olu: tụgharịa imi gị gaa n''okpuru ogwe aka gị, wee jiri nwayọ lee ala.', 'Akwara ihu olu: jiri nwayọ hulata isi gị azụ ntakịrị na n''akụkụ, ka aka gị na-ejide ọkpụkpụ olu-obi ala.', 'Jide ọgbatị ọ bụla sekọnd 30, ugboro 2 ruo 3 n''akụkụ ọ bụla.']::text[], null, null, 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('nk-3stretch', 'yo', array['Iṣan òkè èjìká: tẹ etí rẹ sí èjìká rẹ kí o sì dì í mú.', 'Iṣan ẹ̀gbẹ́ ọrùn: yí imú rẹ sí abíyá rẹ, lẹ́yìn náà rọra wo ilẹ̀.', 'Iṣan iwájú ọrùn: rọra tẹ orí rẹ sẹ́yìn díẹ̀ àti sí ẹ̀gbẹ́, kí o fi ọwọ́ mú egungun ọrùn-àyà sílẹ̀.', 'Dì ìfàsẹ́yìn kọ̀ọ̀kan mú fún ìṣẹ́jú-àáyá 30, ní ìgbà 2 sí 3 ní ẹ̀gbẹ́ kọ̀ọ̀kan.']::text[], null, null, 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('nk-aaa', 'en', array['NHS web page with mobility, deep neck strengthening, balance and nerve-glide exercises.', 'Start with section 1 (mobility) and move on only when it is comfortable.', 'Printable versions of each section are linked on the page.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('nk-band-ext', 'en', array['Sit tall. Hold a resistance band or towel around the back of your head with both hands in front.', 'Gently push your head back into the band while your hands stop it moving far.', 'Keep your chin slightly tucked and move slowly.', 'Do 15 repetitions, 3 times.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('nk-band-warm', 'en', array['Use a light resistance band. Hold it in front of you with both hands.', 'Pull the band apart while squeezing the shoulder blades back. Keep shoulders down.', 'Follow the other band movements in the video slowly.', 'Do 10 to 15 repetitions of each, once a day.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('nk-chin-lying', 'en', array['Lie on your back with your knees bent and your head on a thin pillow or folded towel.', 'Gently tuck your chin in, as if making a small double chin. Keep your head on the pillow.', 'Hold for up to 60 seconds while breathing normally.', 'Rest, then repeat 3 times. Do this 3 times a day.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('nk-chin-lying', 'ha', array['Kwanta a bayanka, gwiwoyinka a lanƙwashe, kanka a kan ƙaramin matashin kai.', 'A hankali ka janye haɓarka ciki, kamar kana yin haɓa biyu. Bar kanka a kan matashin.', 'Ka riƙe har zuwa daƙiƙa 60, kana numfashi kamar yadda ka saba.', 'Ka huta, sannan ka maimaita sau uku. Yi wannan sau uku a rana.']::text[], null, null, 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('nk-chin-lying', 'ig', array['Dinara n''azụ gị, ikpere gị ehulata, isi gị n''elu ohiri isi dị gịrịgịrị.', 'Jiri nwayọ dọghachi agba gị azụ, dị ka ị na-eme agba abụọ. Hapụ isi gị n''elu ohiri isi.', 'Jide ya ruo sekọnd 60, ka ị na-eku ume nke ọma.', 'Zuru ike, wee mee ya ugboro atọ. Mee nke a ugboro atọ kwa ụbọchị.']::text[], null, null, 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('nk-chin-lying', 'yo', array['Dùbúlẹ̀ lórí ẹ̀yìn rẹ, kí orúnkún rẹ tẹ̀, kí orí rẹ wà lórí ìrọ̀rí tínrín.', 'Rọra fa àgbọ̀n rẹ wọlé, bí ẹni pé o fẹ́ ṣe àgbọ̀n méjì. Jẹ́ kí orí rẹ wà lórí ìrọ̀rí.', 'Dì í mú títí dé ìṣẹ́jú-àáyá 60, kí o máa mí dáadáa.', 'Sinmi, kí o tún un ṣe ní ìgbà mẹ́ta. Ṣe é ní ìgbà mẹ́ta lójúmọ́.']::text[], null, null, 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('nk-chin-sit', 'en', array['Sit tall with your back supported and shoulders relaxed.', 'Slide your chin straight back, keeping your eyes level. Do not tip your head down.', 'Hold for up to 60 seconds while breathing normally.', 'Repeat 3 times, 3 times a day.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('nk-chin-sit', 'ha', array['Zauna a miƙe bayanka a jingine, kafaɗunka a sake.', 'Ka janye haɓarka baya kai tsaye, idanunka suna kallon gaba. Kada ka sunkuyar da kai.', 'Ka riƙe har zuwa daƙiƙa 60, kana numfashi kamar yadda ka saba.', 'Yi sau uku, sau uku a rana.']::text[], null, null, 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('nk-chin-sit', 'ig', array['Nọdụ ala ọtọ, azụ gị dabere n''ihe, ubu gị dị jụụ.', 'Dọghachi agba gị azụ kpọmkwem, anya gị na-ele n''ihu. Ehulatala isi.', 'Jide ya ruo sekọnd 60, ka ị na-eku ume nke ọma.', 'Mee ya ugboro atọ, ugboro atọ kwa ụbọchị.']::text[], null, null, 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('nk-chin-sit', 'yo', array['Jókòó ṣánṣán kí ẹ̀yìn rẹ fara tì, kí èjìká rẹ rọ̀.', 'Fa àgbọ̀n rẹ padà sẹ́yìn tààrà, kí ojú rẹ wà ní ìpele kan. Má ṣe tẹ orí sílẹ̀.', 'Dì í mú títí dé ìṣẹ́jú-àáyá 60, kí o máa mí dáadáa.', 'Ṣe é ní ìgbà mẹ́ta, ní ìgbà mẹ́ta lójúmọ́.']::text[], null, null, 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('nk-desk-pdf', 'en', array['Printable sheet of neck movements, side-bend stretch, levator scapulae stretch, chest stretch and chin tuck.', 'Includes upper back extension over a rolled towel on a chair.', 'Do 2 or 3 of these stretches every 45 to 60 minutes when working at a desk.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('nk-disc', 'en', array['Sit tall. Start with gentle chin tucks to find a comfortable middle position.', 'Follow the video for small, pain-free movements of the neck.', 'Move only within a comfortable range. Pain should not spread further down your arm.', 'Repeat 8 to 10 times, a few times a day.']::text[], null, 'Stop if arm pain, numbness or tingling spreads further down the arm.', 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('nk-flex-ext', 'en', array['Sit tall on a chair with your shoulders relaxed.', 'Slowly nod your chin down towards your chest and hold for 5 seconds.', 'Come back to the middle, then slowly look up towards the ceiling and hold for 5 seconds.', 'Move only as far as is comfortable. Repeat 20 times, 3 times a day.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('nk-flex-ext', 'ha', array['Zauna a miƙe a kan kujera, kafaɗunka a sake.', 'A hankali ka sunkuyar da haɓarka zuwa ƙirjinka, ka riƙe na daƙiƙa 5.', 'Ka dawo tsakiya, sannan a hankali ka kalli sama, ka riƙe na daƙiƙa 5.', 'Kada ka wuce inda ya dace maka. Yi sau 20, sau uku a rana.']::text[], null, null, 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('nk-flex-ext', 'ig', array['Nọdụ ala ọtọ n''oche, hapụ ubu gị ka ọ dị jụụ.', 'Jiri nwayọ hulata agba gị n''obi gị, jide ya sekọnd 5.', 'Laghachi n''etiti, wee jiri nwayọ lee elu n''uko ụlọ, jide ya sekọnd 5.', 'Gaa naanị ebe dị gị mma. Mee ya ugboro 20, ugboro atọ kwa ụbọchị.']::text[], null, null, 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('nk-flex-ext', 'yo', array['Jókòó ṣánṣán lórí àga, kí èjìká rẹ rọ̀.', 'Rọra tẹ àgbọ̀n rẹ sílẹ̀ sí àyà rẹ, kí o sì dì í mú fún ìṣẹ́jú-àáyá 5.', 'Padà sí àárín, lẹ́yìn náà rọra wo òkè àjà, kí o dì í mú fún ìṣẹ́jú-àáyá 5.', 'Má ṣe kọjá ibi tí ó rọrùn fún ọ. Ṣe é ní ìgbà 20, ní ìgbà mẹ́ta lójúmọ́.']::text[], null, null, 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('nk-floss', 'en', array['Sit tall. Lift the affected arm out to the side at shoulder height.', 'Tip your head towards the arm while bending the wrist down, then tip the head away while lifting the wrist.', 'Keep the movement smooth and gentle, without holding at the end.', 'Do 10 slow repetitions, 2 to 3 times a day.']::text[], null, 'Stop if arm tingling or pain increases and does not settle within a few minutes.', 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('nk-kenway', 'en', array['Follow along with this 15-minute seated routine.', 'It includes gentle neck turns, side bends, shoulder rolls and upper back stretches.', 'Move slowly and breathe out as you stretch.', 'Do the full routine once a day, or a few stretches during work breaks.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('nk-median', 'en', array['Stand or sit tall. Lift your arm out to the side with the palm facing up and the elbow bent.', 'Slowly straighten the elbow and bend the wrist back while tipping your head away from the arm.', 'Then bend the elbow and tip your head towards the arm. This is one glide.', 'Move smoothly for 30 seconds, several times a day. It should never be forced.']::text[], null, 'Stop if tingling or arm pain increases and stays after the exercise.', 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('nk-side', 'en', array['Sit tall and look straight ahead.', 'Slowly tip your ear towards your shoulder. Do not lift the shoulder.', 'Hold for 5 seconds, return to the middle, then go to the other side.', 'Repeat 20 times each side, 3 times a day.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('nk-side', 'ha', array['Zauna a miƙe ka kalli gaba.', 'A hankali ka karkata kunnenka zuwa kafaɗarka. Kada ka ɗaga kafaɗar.', 'Ka riƙe na daƙiƙa 5, ka dawo tsakiya, sannan ka yi ɗaya gefen.', 'Yi sau 20 a kowane gefe, sau uku a rana.']::text[], null, null, 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('nk-side', 'ig', array['Nọdụ ala ọtọ, lee anya n''ihu.', 'Jiri nwayọ hulata ntị gị n''ubu gị. Ebuliela ubu ahụ.', 'Jide ya sekọnd 5, laghachi n''etiti, wee mee n''akụkụ nke ọzọ.', 'Mee ya ugboro 20 n''akụkụ ọ bụla, ugboro atọ kwa ụbọchị.']::text[], null, null, 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('nk-side', 'yo', array['Jókòó ṣánṣán kí o sì wo iwájú.', 'Rọra tẹ etí rẹ sí èjìká rẹ. Má ṣe gbé èjìká sókè.', 'Dì í mú fún ìṣẹ́jú-àáyá 5, padà sí àárín, lẹ́yìn náà ṣe ẹ̀gbẹ́ kejì.', 'Ṣe é ní ìgbà 20 ní ẹ̀gbẹ́ kọ̀ọ̀kan, ní ìgbà mẹ́ta lójúmọ́.']::text[], null, null, 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('nk-strength-jo', 'en', array['Sit tall. Place your hand on your forehead and gently push your head into it without moving. Hold 5 seconds.', 'Repeat with the hand on the back of the head and each side of the head.', 'Use only gentle pressure, about a third of your effort.', 'Repeat 10 times in each direction, once or twice a day.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('nk-tos', 'en', array['Start with gentle stretches for the side of the neck and the chest.', 'Practise relaxed breathing using the belly rather than the upper chest.', 'Strengthen the shoulder blade muscles with slow, controlled movements.', 'Do about 10 repetitions of each exercise once a day.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('nk-trap-ball', 'en', array['Stand with your back against a wall and place a tennis ball between the wall and the tight muscle at the top of your shoulder or between the shoulder blades.', 'Lean gently into the ball and roll slowly over the tender spot.', 'Stay on a tender spot for 20 to 30 seconds while breathing slowly.', 'Use light pressure. Do not press on the spine or on the front of the neck.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('nk-trap-st', 'en', array['Sit tall and hold the edge of the chair with one hand to keep that shoulder down.', 'Tip your ear away from that side towards the other shoulder.', 'You may use the other hand to add very light pressure.', 'Hold 30 seconds, 3 times each side.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('nk-trap-st', 'ha', array['Zauna a miƙe, ka riƙe gefen kujera da hannu ɗaya don kafaɗar wannan gefe ta zauna a ƙasa.', 'Ka karkata kunnenka nesa da wannan gefe zuwa ɗayan kafaɗa.', 'Kana iya amfani da ɗayan hannu ka ɗan matsa a hankali.', 'Riƙe na daƙiƙa 30, sau uku a kowane gefe.']::text[], null, null, 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('nk-trap-st', 'ig', array['Nọdụ ala ọtọ, were otu aka jide ọnụ oche ka ubu akụkụ ahụ nọrọ ala.', 'Hulata ntị gị pụọ n''akụkụ ahụ gaa n''ubu nke ọzọ.', 'Ị nwere ike iji aka nke ọzọ pịa ya nwayọ nwayọ.', 'Jide ya sekọnd 30, ugboro atọ n''akụkụ ọ bụla.']::text[], null, null, 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('nk-trap-st', 'yo', array['Jókòó ṣánṣán, fi ọwọ́ kan mú etí àga kí èjìká ẹ̀gbẹ́ yẹn lè wà nísàlẹ̀.', 'Tẹ etí rẹ kúrò ní ẹ̀gbẹ́ yẹn sí èjìká kejì.', 'O lè fi ọwọ́ kejì tẹ̀ ẹ́ díẹ̀ jẹ́jẹ́.', 'Dì í mú fún ìṣẹ́jú-àáyá 30, ní ìgbà mẹ́ta ní ẹ̀gbẹ́ kọ̀ọ̀kan.']::text[], null, null, 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('nk-trap-st2', 'en', array['Sit tall with shoulders relaxed.', 'Bring one arm behind your back or hold the chair to keep the shoulder down.', 'Tilt your head away and slightly turn it until you feel a gentle stretch at the top of the shoulder.', 'Hold 20 to 30 seconds and repeat 2 to 3 times each side.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('nk-upper-cross-cw', 'en', array['Start with a chest stretch: arms on a door frame, lean gently forwards until you feel a stretch in the front of the chest.', 'Then do chin tucks: slide your chin straight back and hold for a few seconds.', 'Then squeeze your shoulder blades gently back and down.', 'Do each exercise for about 10 slow repetitions or 30 seconds, once or twice a day.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('nk-upper-cross-pdf', 'en', array['Printable leaflet with stretches and strengthening for forward head and rounded shoulders.', 'Do the stretches gently and hold each for about 30 seconds.', 'Do the strengthening exercises slowly, about 10 repetitions each.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('nk-upper-cross-pt101', 'en', array['Stretch the chest and the front of the neck gently, holding about 30 seconds.', 'Strengthen the deep neck muscles with chin tucks.', 'Strengthen the muscles between the shoulder blades by drawing them back and down.', 'Repeat 10 times for strengthening moves, once or twice a day.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('nk-upper-cross-tm', 'en', array['Follow the video for gentle stretches of the chest and the top of the shoulders.', 'Add strengthening of the muscles between the shoulder blades, such as rows or shoulder blade squeezes.', 'Keep movements slow and controlled with relaxed breathing.', 'Aim for 10 repetitions of each strengthening exercise and 30-second stretches.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('nk-whiplash', 'en', array['Start with gentle neck turns and nods within a comfortable range.', 'Add chin tucks to wake up the deep neck muscles.', 'Add shoulder blade squeezes and gentle shoulder rolls.', 'Keep moving little and often, about 10 repetitions each, 2 to 3 times a day.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('sh-aaa-stiff', 'en', array['NHS web page with three levels of exercises for a stiff shoulder, each with a video.', 'Gentle, regular movement matters more than pushing hard.', 'Move on to the next level when the current one is comfortable.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('sh-aaa-weak', 'en', array['NHS web page with three levels of shoulder strengthening, each with a short video.', 'Start at level 1 and move to the next level when it feels easy.', 'Includes advice on how much discomfort is acceptable.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('sh-ass-abd', 'en', array['Hold a stick with both hands.', 'Use the good arm to help push the painful arm out to the side and up.', 'Go only as far as a comfortable stretch, then lower slowly.', 'Do 15 repetitions, 3 times a day.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('sh-ass-ext-rot', 'en', array['Lie or sit with your elbows tucked into your sides and bent to 90 degrees, holding a stick.', 'Use the good arm to push the stick so the painful arm''s hand moves outwards.', 'Keep the elbow at your side. Go to a comfortable stretch and come back.', 'Do 15 repetitions, 3 times a day, building to 3 sets of 15.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('sh-coyner', 'en', array['Printable sheet of resistance band shoulder exercises.', 'Use a light band first. Move slowly in both directions.', 'Aim for 10 to 15 repetitions as your specialist advises.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('sh-crossbody', 'en', array['Stand or sit tall.', 'Bring the painful arm across your chest.', 'Use the other hand to gently pull it closer at the elbow until you feel a stretch at the back of the shoulder.', 'Hold 20 seconds, repeat 5 times.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('sh-doorway', 'en', array['Stand in a doorway with your forearm on the door frame, elbow at shoulder height.', 'Step forward gently with one foot until you feel a stretch across the front of the shoulder and chest.', 'Keep your back straight and breathe normally.', 'Hold 20 seconds, repeat 5 times.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('sh-doorway', 'ha', array['Tsaya a bakin ƙofa, ka ɗora hannunka a kan firam, gwiwar hannu daidai da kafaɗa.', 'A hankali ka taka gaba da ƙafa ɗaya har ka ji miƙewa a gaban kafaɗa da ƙirji.', 'Bayanka a miƙe, kana numfashi kamar yadda ka saba.', 'Riƙe na daƙiƙa 20, sau 5.']::text[], null, null, 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('sh-doorway', 'ig', array['Guzoro n''ọnụ ụzọ, were aka gị dabere n''osisi ọnụ ụzọ, ikpere aka n''ọkwa ubu.', 'Jiri nwayọ zọọ otu ụkwụ n''ihu ruo mgbe ị nwere ọgbatị n''ihu ubu na obi.', 'Mee ka azụ gị kwụ ọtọ, kuo ume nke ọma.', 'Jide ya sekọnd 20, mee ya ugboro 5.']::text[], null, null, 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('sh-doorway', 'yo', array['Dúró ní ẹnu ọ̀nà, kí apá-iwájú rẹ wà lórí férémù ilẹ̀kùn, ìgúnpá ní ìpele èjìká.', 'Rọra gbé ẹsẹ̀ kan síwájú títí o fi máa ní ìfàsẹ́yìn ní iwájú èjìká àti àyà.', 'Jẹ́ kí ẹ̀yìn rẹ wà ní tààrà kí o sì máa mí dáadáa.', 'Dì í mú fún ìṣẹ́jú-àáyá 20, ní ìgbà 5.']::text[], null, null, 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('sh-frozen-pdf', 'en', array['Explains what a frozen shoulder is, its stages, and how long it usually takes to recover.', 'Includes gentle exercises to keep the shoulder moving.', 'Pain relief and gentle movement are the main treatments.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('sh-iso-abd', 'en', array['Stand side-on to a wall with your elbow bent and the outside of your elbow touching the wall.', 'Push the elbow gently into the wall without moving.', 'Hold 10 seconds and build up to 40 seconds over 4 weeks.', 'Repeat 5 times, 4 times a day.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('sh-iso-er', 'en', array['Stand side-on to a wall with your elbow bent to 90 degrees and tucked into your side.', 'Press the back of your wrist gently into the wall without moving the arm.', 'Hold 10 seconds in week 1, 20 in week 2, 30 in week 3 and 40 in week 4.', 'Repeat 5 times, 4 times a day.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('sh-iso-er', 'ha', array['Tsaya gefenka yana fuskantar bango, gwiwar hannunka a lanƙwashe kamar kusurwa, a manne da gefenka.', 'A hankali ka matsa bayan wuyan hannunka a kan bango ba tare da motsa hannu ba.', 'Riƙe na daƙiƙa 10 a mako na farko, 20 a na biyu, 30 a na uku, 40 a na huɗu.', 'Yi sau 5, sau huɗu a rana.']::text[], null, null, 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('sh-iso-er', 'ig', array['Guzoro n''akụkụ mgbidi, ikpere aka gị ehulata n''akụkụ anọ, dabere n''akụkụ ahụ gị.', 'Jiri nwayọ pịa azụ nkwonkwo aka gị na mgbidi n''emeghị ka aka megharịa.', 'Jide ya sekọnd 10 n''izu mbụ, 20 n''izu nke abụọ, 30 n''izu nke atọ, 40 n''izu nke anọ.', 'Mee ya ugboro 5, ugboro anọ kwa ụbọchị.']::text[], null, null, 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('sh-iso-er', 'yo', array['Dúró pẹ̀lú ẹ̀gbẹ́ rẹ sí ògiri, kí ìgúnpá rẹ tẹ̀ ní igun mẹ́rin, kí ó sì wà lẹ́gbẹ̀ẹ́ ara rẹ.', 'Rọra tẹ ẹ̀yìn ọrùn-ọwọ́ rẹ mọ́ ògiri láìsí pé apá ń gbéra.', 'Dì í mú fún ìṣẹ́jú-àáyá 10 ní ọ̀sẹ̀ kìíní, 20 ní ọ̀sẹ̀ kejì, 30 ní ọ̀sẹ̀ kẹta, 40 ní ọ̀sẹ̀ kẹrin.', 'Ṣe é ní ìgbà 5, ní ìgbà mẹ́rin lójúmọ́.']::text[], null, null, 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('sh-pendular', 'en', array['Lean forwards and support yourself with your good hand on a table.', 'Let the painful arm hang down loosely.', 'Gently sway your body so the arm swings forwards and back, then side to side, then in small circles.', 'Do 15 of each, building to 3 sets of 15.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('sh-pendular', 'ha', array['Ka sunkuya gaba, ka jingina da hannunka mai lafiya a kan tebur.', 'Ka bar hannun da ke ciwo ya rataya a sake.', 'A hankali ka girgiza jikinka don hannun ya yi lilo gaba da baya, sannan gefe da gefe, sannan ƙananan da''irori.', 'Yi kowanne sau 15, har zuwa zagaye uku na 15.']::text[], null, null, 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('sh-pendular', 'ig', array['Hulata n''ihu, were aka gị dị mma dabere na tebụl.', 'Hapụ aka na-afụ ụfụ ka ọ kwụdata ala n''enweghị ike.', 'Jiri nwayọ megharịa ahụ gị ka aka ahụ fee n''ihu na azụ, wee n''akụkụ, wee na gburugburu nta.', 'Mee nke ọ bụla ugboro 15, ruo usoro atọ nke 15.']::text[], null, null, 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('sh-pendular', 'yo', array['Tẹ̀ síwájú kí o sì fi ọwọ́ dáradára rẹ ti tábìlì.', 'Jẹ́ kí apá tí ó ń dùn ọ́ rọ̀ sílẹ̀ láìsí agbára.', 'Rọra mì ara rẹ kí apá náà lè yí síwájú àti sẹ́yìn, lẹ́yìn náà sí ẹ̀gbẹ́, lẹ́yìn náà ní òbìrí kékeré.', 'Ṣe ọ̀kọ̀ọ̀kan ní ìgbà 15, títí dé ìpele mẹ́ta ti 15.']::text[], null, null, 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('sh-row', 'en', array['Tie a resistance band to a door handle at waist height and hold one end in each hand.', 'Stand tall and pull your elbows back, squeezing your shoulder blades together.', 'Slowly return to the start.', 'Do 15 repetitions, building to 3 sets of 15.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('sh-row', 'ha', array['Ka ɗaure igiyar roba a hannun ƙofa daidai da kugu, ka riƙe ƙarshe ɗaya a kowane hannu.', 'Tsaya a miƙe ka ja gwiwoyin hannunka baya, kana matse ƙasusuwan bayan kafaɗa wuri ɗaya.', 'A hankali ka koma farko.', 'Yi sau 15, har zuwa zagaye uku na 15.']::text[], null, null, 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('sh-row', 'ig', array['Kee eriri rọba na mkpọchi ọnụ ụzọ n''ọkwa úkwù, jide otu nsọtụ n''aka ọ bụla.', 'Guzoro ọtọ, dọghachi ikpere aka gị azụ, pịkọta ọkpụkpụ azụ ubu gị ọnụ.', 'Jiri nwayọ laghachi ebe ị malitere.', 'Mee ya ugboro 15, ruo usoro atọ nke 15.']::text[], null, null, 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('sh-row', 'yo', array['So okùn rọ́bà mọ́ ìdí ilẹ̀kùn ní ìpele ìbàdí, mú etí kọ̀ọ̀kan ní ọwọ́ kọ̀ọ̀kan.', 'Dúró ṣánṣán kí o fa ìgúnpá rẹ sẹ́yìn, kí o sì fún abẹ́ èjìká rẹ papọ̀.', 'Rọra padà sí ibi tí o ti bẹ̀rẹ̀.', 'Ṣe é ní ìgbà 15, títí dé ìpele mẹ́ta ti 15.']::text[], null, null, 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('sh-scap-set', 'en', array['Sit or stand tall with arms relaxed.', 'Gently draw your shoulder blades back and down, as if putting them into your back pockets.', 'Hold for a few seconds without shrugging, then relax.', 'Do 15 repetitions, building to 3 sets of 15.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('sh-scaption', 'en', array['Stand tall holding a light weight or a filled water bottle, thumbs pointing up.', 'Lift your arms forwards and slightly out (like a V) up to shoulder height.', 'Lower slowly.', 'Do 15 repetitions, building to 3 sets of 15.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('sh-ucsf', 'en', array['Printable programme from shoulder blade squeezes and wall angels to band exercises and push-up plus.', 'Start with the easier exercises and progress only if pain stays settled.', 'Your specialist will tell you which exercises and how many.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('sh-wallpress', 'en', array['Stand an arm''s length from a wall with hands flat on it at shoulder height.', 'Bend your elbows to bring your chest towards the wall, keeping your body straight.', 'Push back to the start.', 'Do 15 repetitions, building to 3 sets of 15.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('sh-wallpress', 'ha', array['Tsaya nisan tsawon hannu daga bango, tafukan hannunka a kan bango daidai da kafaɗa.', 'Ka lanƙwasa gwiwoyin hannunka don ƙirjinka ya kusanci bango, jikinka a miƙe.', 'Ka tura baya zuwa farko.', 'Yi sau 15, har zuwa zagaye uku na 15.']::text[], null, null, 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('sh-wallpress', 'ig', array['Guzoro ihe dị ka ogologo aka site na mgbidi, aka gị n''elu ya n''ọkwa ubu.', 'Hulata ikpere aka gị ka obi gị bịaruo mgbidi nso, ahụ gị kwụ ọtọ.', 'Kwagharịa laghachi ebe ị malitere.', 'Mee ya ugboro 15, ruo usoro atọ nke 15.']::text[], null, null, 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('sh-wallpress', 'yo', array['Dúró ní ìwọ̀n gígùn apá kan sí ògiri, kí àtẹ́lẹwọ́ rẹ wà lórí rẹ̀ ní ìpele èjìká.', 'Tẹ ìgúnpá rẹ láti mú àyà rẹ súnmọ́ ògiri, kí ara rẹ wà ní tààrà.', 'Tì í padà sí ibi tí o ti bẹ̀rẹ̀.', 'Ṣe é ní ìgbà 15, títí dé ìpele mẹ́ta ti 15.']::text[], null, null, 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('st-back', 'en', array['Stand with feet hip-width apart.', 'Slowly bend forwards and note where your fingertips reach (thighs, knees, shins, floor).', 'Slowly lean back and side to side. Note any pain and where you feel it.', 'Record your results weekly.']::text[], null, 'Stop if pain spreads down a leg, or if you feel numbness or weakness.', 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('st-back', 'ha', array['Tsaya ƙafafunka a buɗe daidai da kugu.', 'A hankali ka sunkuya gaba ka lura da inda yatsunka suka kai (cinya, gwiwa, ƙwauri, ƙasa).', 'A hankali ka karkata baya da gefe-gefe. Lura da ciwo da inda kake jin sa.', 'Rubuta sakamakonka kowane mako.']::text[], null, 'Ka daina idan ciwo yana bazuwa zuwa ƙafa, ko kana jin dushewa ko rauni.', 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('st-back', 'ig', array['Guzoro, ụkwụ gị gbasaa dị ka úkwù.', 'Jiri nwayọ hulata n''ihu, hụ ebe mkpịsị aka gị ruru (apata, ikpere, ọkpụkpụ ụkwụ, ala).', 'Jiri nwayọ hulata azụ na n''akụkụ abụọ. Hụ mgbu ọ bụla na ebe ị na-enwe ya.', 'Dee nsonaazụ gị kwa izu.']::text[], null, 'Kwụsị ma mgbu na-agbada n''otu ụkwụ, ma ọ bụ ị nwere ahụ ịnwụ anwụ ma ọ bụ adịghị ike.', 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('st-back', 'yo', array['Dúró kí ẹsẹ̀ rẹ jìnnà síra bí ìbàdí.', 'Rọra tẹ̀ síwájú kí o sì ṣàkíyèsí ibi tí ìka ọwọ́ rẹ dé (itan, orúnkún, ojúgun, ilẹ̀).', 'Rọra tẹ̀ sẹ́yìn àti sí ẹ̀gbẹ́ méjèèjì. Ṣàkíyèsí ìrora àti ibi tí o ti ń ní i.', 'Kọ èsì rẹ sílẹ̀ lọ́sọ̀ọ̀sẹ̀.']::text[], null, 'Dáwọ́ dúró bí ìrora bá ń lọ sí ẹsẹ̀ kan, tàbí bí o bá ní ìkú-ara tàbí àìlágbára.', 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('st-calf', 'en', array['Stand on one leg holding a worktop for balance.', 'Rise up onto your toes as high as you can and lower slowly, about one per second.', 'Count how many full raises you can do before you tire or the height drops.', 'Do both legs and write down the numbers.']::text[], null, 'Stop if you feel a sudden snap or sharp pain at the back of the heel.', 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('st-hand', 'en', array['Rest your forearm on a table.', 'Make a full fist, then spread your fingers wide.', 'Note whether your fingertips touch your palm and if the fingers straighten fully.', 'Touch your thumb to each fingertip. Compare both hands weekly.']::text[], null, 'Stop if you get new numbness or the fingers lock.', 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('st-hip', 'en', array['Sit on a chair.', 'Try to put on a sock or touch your foot by bending the knee up towards you.', 'Note if it is easy, possible with effort, or not possible.', 'Repeat on both sides each week.']::text[], null, 'Stop if you have had a hip replacement and your team told you to avoid bending this far.', 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('st-knee', 'en', array['Sit on the floor or a bed with legs straight.', 'Tighten your thigh and check if the back of the knee can touch the bed.', 'Slide your heel towards you to bend the knee as far as is comfortable. Note the distance from heel to bottom.', 'Compare both knees and repeat each week.']::text[], null, 'Stop if the knee locks and will not straighten, or swells quickly.', 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('st-neck', 'en', array['Sit tall in front of a mirror.', 'Slowly turn your head to look over each shoulder. Note how far you can turn and where it pulls.', 'Slowly tip your ear to each shoulder, then look down and up.', 'Score each movement: easy, stiff, or painful. Compare each week.']::text[], null, 'Stop if you feel dizzy, have blurred or double vision, or pain or tingling spreads into your arm.', 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('st-neck', 'ha', array['Zauna a miƙe a gaban madubi.', 'A hankali ka juya kanka ka kalli kowace kafaɗa. Lura da nisan da za ka iya juyawa da inda yake ja.', 'A hankali ka karkata kunnenka zuwa kowace kafaɗa, sannan ka kalli ƙasa da sama.', 'Ba kowane motsi maki: mai sauƙi, mai tauri, ko mai ciwo. Kwatanta kowane mako.']::text[], null, 'Ka daina idan kana jin jiri, ganinka ya dushe ko ya ninka, ko ciwo ko tsinkewa ya bazu zuwa hannunka.', 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('st-neck', 'ig', array['Nọdụ ala ọtọ n''ihu enyo.', 'Jiri nwayọ tụgharịa isi gị lee n''elu ubu ọ bụla. Hụ ebe ị nwere ike iru na ebe ọ na-adọ.', 'Jiri nwayọ hulata ntị gị n''ubu ọ bụla, wee lee ala na elu.', 'Nye mmegharị ọ bụla akara: mfe, siri ike, ma ọ bụ na-afụ ụfụ. Tụnyere kwa izu.']::text[], null, 'Kwụsị ma isi na-agba gị gburugburu, anya na-ahụ ihe abụọ ma ọ bụ na-ajọ, ma ọ bụ mgbu na-agbada n''aka gị.', 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('st-neck', 'yo', array['Jókòó ṣánṣán níwájú dígí.', 'Rọra yí orí rẹ láti wo orí èjìká kọ̀ọ̀kan. Ṣàkíyèsí bí o ti lè yí tó àti ibi tí ó ti ń fà.', 'Rọra tẹ etí rẹ sí èjìká kọ̀ọ̀kan, lẹ́yìn náà wo ilẹ̀ àti òkè.', 'Fún ìgbésẹ̀ kọ̀ọ̀kan ní àmì: rọrùn, le, tàbí ń dùn. Fi wé ara wọn lọ́sọ̀ọ̀sẹ̀.']::text[], null, 'Dáwọ́ dúró bí òòyì bá ń kọ́ ọ, bí ojú rẹ bá ń ríran méjì tàbí ṣókùnkùn, tàbí bí ìrora bá ń lọ sí apá rẹ.', 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('st-shoulder', 'en', array['Stand in front of a mirror.', 'Lift each arm forwards and up as high as you can. Note where it stops or hurts.', 'Place your hand behind your head, then behind your lower back. Note how far you reach.', 'Compare left and right, and repeat each week.']::text[], null, 'Stop if the shoulder feels like it slips out, or if you get sudden severe pain.', 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('st-slb', 'en', array['Stand next to a kitchen worktop or sturdy chair, with your hand just above it.', 'Lift one foot off the floor and time how long you can stand still, up to 30 seconds.', 'Do each leg twice and write down your best time for each.', 'Compare the two sides and repeat every 2 to 4 weeks.']::text[], null, 'Stop and hold on if you feel unsteady. Do not try this alone if you have fallen recently.', 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('st-slb', 'ha', array['Tsaya kusa da teburin kicin ko kujera mai ƙarfi, hannunka kaɗan a samansa.', 'Ɗaga ƙafa ɗaya daga ƙasa ka auna tsawon lokacin da za ka iya tsayawa cak, har zuwa daƙiƙa 30.', 'Yi kowace ƙafa sau biyu ka rubuta mafi kyawun lokaci.', 'Kwatanta ɓangarorin biyu ka maimaita kowane mako 2 zuwa 4.']::text[], null, 'Ka tsaya ka riƙe idan kana jin rashin daidaito. Kada ka yi kai kaɗai idan ka faɗi kwanan nan.', 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('st-slb', 'ig', array['Guzoro n''akụkụ tebụl kichin ma ọ bụ oche siri ike, aka gị n''elu ya ntakịrị.', 'Bulie otu ụkwụ n''ala, gụọ ogologo oge ị nwere ike iguzo jụụ, ruo sekọnd 30.', 'Mee ụkwụ ọ bụla ugboro abụọ, dee oge gị kacha mma.', 'Tụnyere akụkụ abụọ ahụ, mee ya ọzọ kwa izu 2 ruo 4.']::text[], null, 'Kwụsị jide ihe ma ị na-ama jijiji. Emela ya naanị gị ma ọ bụrụ na ị dara n''oge na-adịbeghị anya.', 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('st-slb', 'yo', array['Dúró nítòsí ibi ìdáná tàbí àga tó le, kí ọwọ́ rẹ wà lókè rẹ̀ díẹ̀.', 'Gbé ẹsẹ̀ kan sókè kúrò ní ilẹ̀, kí o sì ka bí o ti lè dúró jẹ́ẹ́ tó, títí dé ìṣẹ́jú-àáyá 30.', 'Ṣe ẹsẹ̀ kọ̀ọ̀kan lẹ́ẹ̀mejì kí o sì kọ àkókò tó dára jùlọ sílẹ̀.', 'Fi ẹ̀gbẹ́ méjèèjì wé ara wọn kí o tún un ṣe ní gbogbo ọ̀sẹ̀ 2 sí 4.']::text[], null, 'Dáwọ́ dúró kí o di nǹkan mú bí o bá ń mì. Má ṣe é ní ìwọ nìkan bí o bá ṣubú láìpẹ́ yìí.', 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('st-sts30', 'en', array['Use a firm chair without wheels, against a wall. Sit in the middle with arms crossed on your chest.', 'When ready, stand up fully and sit back down as many times as you can in 30 seconds.', 'Count the full stands. Write down the number and the date.', 'Repeat every 2 to 4 weeks to see your progress. Your specialist will explain what your number means.']::text[], null, 'Stop if you feel dizzy, chest pain or very short of breath, or if a joint gives way.', 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('st-sts30', 'ha', array['Yi amfani da kujera mai ƙarfi marar taya, a jingine da bango. Zauna a tsakiya, hannunka a haɗe a ƙirji.', 'Idan ka shirya, ka tashi tsaye sosai ka zauna sau nawa za ka iya cikin daƙiƙa 30.', 'Ƙirga cikakkun tsayuwa. Rubuta adadin da kwanan wata.', 'Maimaita kowane mako 2 zuwa 4 don ganin ci gabanka. Ƙwararrenka zai bayyana ma''anar adadinka.']::text[], null, 'Ka daina idan kana jin jiri, ciwon ƙirji, ko numfashi ya yi maka wuya sosai, ko wani gaɓa ya kasa.', 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('st-sts30', 'ig', array['Jiri oche siri ike na-enweghị wiil, dabere na mgbidi. Nọdụ n''etiti ya, aka gị gafere n''obi gị.', 'Mgbe ị dị njikere, bilie kpamkpam ma nọdụ ala ọzọ ugboro ole ị nwere ike n''ime sekọnd 30.', 'Gụọ ugboro ole i biliri. Dee ọnụọgụ ahụ na ụbọchị ya.', 'Mee ya ọzọ kwa izu 2 ruo 4 iji hụ ọganihu gị. Ọkachamara gị ga-akọwa ihe ọnụọgụ gị pụtara.']::text[], null, 'Kwụsị ma isi na-agba gị gburugburu, obi na-afụ gị ụfụ, ume na-akpa gị nke ukwuu, ma ọ bụ nkwonkwo ahụ dara.', 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('st-sts30', 'yo', array['Lo àga tó le láìní kẹ̀kẹ́, tí ó fara ti ògiri. Jókòó sí àárín rẹ̀, kí apá rẹ dábùú lórí àyà.', 'Nígbà tí o bá ṣetán, dìde dáadáa kí o sì jókòó padà ní iye ìgbà tí o bá lè ṣe é láàárín ìṣẹ́jú-àáyá 30.', 'Ka iye ìgbà tí o dìde. Kọ nọ́ńbà náà àti ọjọ́ sílẹ̀.', 'Tún un ṣe ní gbogbo ọ̀sẹ̀ 2 sí 4 láti rí ìlọsíwájú rẹ. Onímọ̀ rẹ yóò ṣàlàyé ohun tí nọ́ńbà rẹ túmọ̀ sí.']::text[], null, 'Dáwọ́ dúró bí òòyì bá ń kọ́ ọ, bí àyà bá ń dùn ọ́, bí èémí bá ń kúrú jù, tàbí bí oríkèé kan bá yẹ̀.', 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('st-tandem', 'en', array['Stand next to a worktop with a hand just above it.', 'Place one foot directly in front of the other, heel touching toes.', 'Time how long you can hold this, up to 30 seconds. Then swap feet.', 'Write down your times.']::text[], null, 'Hold on straight away if you feel unsteady.', 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('st-tandem', 'ha', array['Tsaya kusa da teburin kicin, hannunka kaɗan a samansa.', 'Sa ƙafa ɗaya kai tsaye a gaban ɗayan, diddige yana taɓa yatsu.', 'Auna tsawon lokacin da za ka iya riƙewa, har zuwa daƙiƙa 30. Sannan ka canza ƙafa.', 'Rubuta lokutanka.']::text[], null, null, 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('st-tandem', 'ig', array['Guzoro n''akụkụ tebụl kichin, aka gị n''elu ya ntakịrị.', 'Tinye otu ụkwụ n''ihu nke ọzọ kpọmkwem, ikiri ụkwụ metụ mkpịsị ụkwụ.', 'Gụọ ogologo oge ị nwere ike ijide ya, ruo sekọnd 30. Wee gbanwee ụkwụ.', 'Dee oge gị.']::text[], null, null, 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('st-tandem', 'yo', array['Dúró nítòsí ibi ìdáná kí ọwọ́ rẹ wà lókè rẹ̀ díẹ̀.', 'Gbé ẹsẹ̀ kan sí iwájú èkejì tààrà, kí gìgísẹ̀ kan ìka ẹsẹ̀.', 'Ka bí o ti lè dì í mú tó, títí dé ìṣẹ́jú-àáyá 30. Lẹ́yìn náà pààrọ̀ ẹsẹ̀.', 'Kọ àkókò rẹ sílẹ̀.']::text[], null, null, 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('st-walk', 'en', array['Place a chair with arms against a wall. Mark a spot 3 metres (about 4 big steps) away.', 'Sit with your back against the chair. Ask someone to time you.', 'On ''go'', stand up, walk at your normal safe pace to the mark, turn, walk back and sit down.', 'Write down the time. Use your usual walking aid if you have one.']::text[], null, 'Only do this with another person present. Stop if you feel dizzy or unsteady.', 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('st-walk', 'ha', array['Sa kujera mai hannu a jikin bango. Yi alama a nisan mita 3 (kusan manyan taki huɗu).', 'Zauna bayanka a jingine da kujera. Ka ce wani ya auna lokaci.', 'Idan aka ce ''tafi'', ka tashi, ka yi tafiya a saurinka na lafiya zuwa alamar, ka juya, ka dawo ka zauna.', 'Rubuta lokacin. Yi amfani da sandar tafiyarka idan kana da ita.']::text[], null, 'Ka yi kawai idan akwai wani a wurin. Ka daina idan kana jin jiri ko rashin daidaito.', 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('st-walk', 'ig', array['Tinye oche nwere aka n''akụkụ mgbidi. Kaa akara ebe dị mita 3 (ihe dị ka nnukwu nzọụkwụ anọ).', 'Nọdụ ala, azụ gị dabere n''oche. Gwa mmadụ ka ọ gụọ oge.', 'Mgbe ha kwuru ''gaa'', bilie, jee ije n''ọsọ gị dị nchebe ruo n''akara ahụ, tụgharịa, laghachi wee nọdụ ala.', 'Dee oge ahụ. Jiri osisi ije gị ma ọ bụrụ na i nwere.']::text[], null, 'Mee ya naanị mgbe onye ọzọ nọ. Kwụsị ma isi na-agba gị gburugburu ma ọ bụ ị na-ama jijiji.', 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('st-walk', 'yo', array['Gbé àga onípá sí ògiri. Sàmì sí ibi tó jìnnà ní mítà 3 (bíi ìgbésẹ̀ ńlá mẹ́rin).', 'Jókòó kí ẹ̀yìn rẹ fara ti àga. Ní kí ẹnìkan ka àkókò fún ọ.', 'Nígbà tí wọ́n bá sọ ''lọ'', dìde, rìn ní ìwọ̀n ìrìn rẹ tó ní ààbò dé àmì náà, yípadà, rìn padà kí o sì jókòó.', 'Kọ àkókò náà sílẹ̀. Lo ọ̀pá ìrìn rẹ bí o bá ní.']::text[], null, 'Ṣe é nìkan nígbà tí ẹlòmíràn bá wà níbẹ̀. Dáwọ́ dúró bí òòyì bá ń kọ́ ọ tàbí o bá ń mì.', 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('st-wrist', 'en', array['Press your palms together in front of your chest with fingers pointing up.', 'Slowly lower your hands, keeping the palms together, until you feel a stretch. Note the height.', 'Then put the backs of your hands together, fingers pointing down, and lift slowly.', 'Compare each week.']::text[], null, 'Stop if you feel sharp pain or tingling in the fingers.', 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('th-aaa', 'en', array['NHS web page with mobility and strengthening exercises for the mid back, each with a video.', 'Start with mobility exercises and add strengthening as they become comfortable.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('th-angels', 'en', array['Stand with your back against a wall, arms bent in a goalpost shape against the wall.', 'Slide your arms up the wall as far as is comfortable.', 'Slide them back down, keeping the back and arms near the wall.', 'Do 15 repetitions, 3 times a day.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('th-ball', 'en', array['Place a tennis ball between your upper back and a wall, beside the spine (not on it).', 'Lean into it gently and roll slowly up and down.', 'Pause on tight spots for 20 to 30 seconds.', 'Use comfortable pressure, once or twice a day.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('th-birddog', 'en', array['Start on hands and knees with your back flat.', 'Slowly reach one arm forwards and the opposite leg back.', 'Hold, keeping your back still, then return and change sides.', 'Do 5 to 15 each side, 3 times a day.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('th-chest', 'en', array['NHS leaflet explaining chest wall (musculoskeletal) pain and gentle exercises.', 'Chest wall pain can feel worrying but is often linked to muscles and joints.', 'Always get new chest pain checked first by a doctor.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('th-rhom-door', 'en', array['Hold onto a door frame with both hands at chest height.', 'Sit your hips back and let your upper back round, so your shoulder blades spread apart.', 'Hold 30 seconds while breathing slowly.', 'Repeat 3 times.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('th-rhom', 'en', array['Start with gentle stretches for the area between the shoulder blades.', 'Follow with shoulder blade squeezes to strengthen the muscles.', 'Move slowly and keep the shoulders down.', 'Do 10 repetitions of each strengthening exercise.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('th-scoliosis', 'en', array['Follow the gentle exercises for posture, breathing and trunk strength.', 'Keep movements slow and comfortable.', 'Focus on standing and sitting tall without strain.', 'Do 8 to 10 repetitions of each, once a day.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('th-sidelying', 'en', array['Lie on your side with knees bent and arms straight out in front together.', 'Lift the top arm and open it across to the other side, following it with your eyes.', 'Keep your knees together. Return slowly.', 'Repeat 20 times each side, 3 times a day.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('th-towel', 'en', array['Lie on your back with a rolled towel across your upper back, under your shoulder blades.', 'Support your head with your hands.', 'Gently let your upper back bend back over the towel, then return.', 'Repeat 20 times, 3 times a day.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('th-wallrot', 'en', array['Stand side-on to a wall with your feet a small step away.', 'Turn your upper body towards the wall and place both hands on it.', 'Let your chest and shoulders turn, keeping your hips facing forwards.', 'Repeat 20 times, both sides, 3 times a day.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('wr-bands', 'en', array['Place a rubber band around your fingers and thumb.', 'Open your hand against the band, then close slowly.', 'Follow the other finger spreading and thumb exercises in the video.', 'Do 10 repetitions each, once a day.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('wr-cts-pdf', 'en', array['Explains carpal tunnel syndrome and why symptoms are often worse at night.', 'A wrist splint at night can help keep the wrist straight.', 'Includes gentle exercises and advice about when to seek further help.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('wr-cts', 'en', array['Sit with your elbow bent and your hand in front of you.', 'Follow the video for gentle tendon and nerve gliding: make a fist, straighten the fingers, then gently bend the wrist back.', 'Move slowly. It should not cause strong tingling.', 'Repeat 5 to 10 times, a few times a day.']::text[], null, 'Stop if tingling or numbness increases and does not settle within a few minutes.', 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('wr-dq', 'en', array['Explains pain at the thumb side of the wrist and what makes it worse.', 'Advice on splints, rest from aggravating tasks and gradual return to use.', 'Includes gentle exercises once pain settles.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('wr-dupuytren', 'en', array['Printable programme of finger and hand stretches and strengthening.', 'Stretch the fingers straight gently; do not force them.', 'Your specialist will tell you which exercises to start with.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('wr-fracture-uhn', 'en', array['Sit with your forearm supported on a table.', 'Gently bend the wrist up and down, side to side, and turn the palm up and down.', 'Make a full fist and then straighten the fingers.', 'Do 10 repetitions of each, 3 to 4 times a day.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('wr-fracture', 'en', array['NHS leaflet of exercises to regain movement after a broken wrist.', 'Start only when your treating team says the bone is ready.', 'Some stiffness is normal at first and improves with regular practice.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('wr-gym', 'en', array['Printable sheet: wrist bending up and down, turning the palm up and down, and side to side, against light resistance.', 'Use a light weight or band and move slowly.', 'Do 10 to 15 repetitions of each.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('wr-hand-ot', 'en', array['Put a rubber band around your fingers.', 'Open your fingers against the band, hold briefly, then close.', 'Follow the other finger exercises in the video.', 'Do 10 repetitions each.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('wr-pip', 'en', array['Support the finger just below the middle joint with your other hand.', 'Bend only the middle joint of the finger as far as is comfortable.', 'Straighten it again slowly.', 'Repeat 10 times, a few times a day.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('wr-rbh', 'en', array['NHS leaflet with progressive wrist and forearm strengthening.', 'Start without weight, then add a light weight as advised.', 'Do the exercises slowly in both directions.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('wr-tfcc-nuh', 'en', array['Sit with your forearm supported on a table.', 'Follow the video for slow wrist strengthening with a light weight or band, lifting and lowering under control.', 'Keep movements within a comfortable range.', 'Do 10 to 15 repetitions of each, once a day.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('wr-tfcc-rs', 'en', array['Start with gentle wrist movements in all directions.', 'Progress to grip and forearm turning exercises with light resistance.', 'Avoid forceful twisting and leaning on the hand while it is painful.', 'Do 10 to 15 repetitions of each.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('wr-thenar', 'en', array['Rest your hand on a table.', 'Follow the video to strengthen the muscles at the base of the thumb, for example pressing the thumb out against a rubber band.', 'Keep the thumb joint in a gentle C shape, not collapsed.', 'Do 10 repetitions, once or twice a day.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('wr-thumb-10x', 'en', array['Loop a rubber band around your thumb and fingers.', 'Spread the thumb away against the band in different directions as shown.', 'Move slowly and with control.', 'Do 10 repetitions of each direction.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('wr-thumb-1hp', 'en', array['Put a rubber band around your thumb and index finger.', 'Move the thumb away from the hand against the band, then return slowly.', 'Keep the movement gentle and controlled.', 'Do 10 to 15 repetitions, 2 to 3 sets.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('wr-thumb-oa', 'en', array['Explains thumb base arthritis and how to protect the joint in daily tasks.', 'Includes thumb strengthening exercises.', 'Advice on gadgets and splints that make tasks easier.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('wr-thumb-rmp', 'en', array['Rest your forearm on a table with a band around the thumb.', 'Move the thumb out against the band and return slowly.', 'Do not let the thumb joint collapse inwards.', 'Do 10 repetitions, twice a day.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('xc-bone-ios', 'en', array['Follow along with safe strengthening exercises for bone health.', 'Use a support where shown.', 'Aim for 2 to 3 times a week.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('xc-bone-ros', 'en', array['Bones need regular impact and muscle strengthening to stay strong.', 'Good nutrition with enough calcium and vitamin D helps.', 'Avoid smoking and limit alcohol.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('xc-bppv', 'en', array['NHS leaflet for home exercises for benign positional vertigo (BPPV).', 'Sit on the edge of the bed, lie quickly to one side, wait, sit up, then lie to the other side.', 'Expect some dizziness during the exercise. Have someone with you at first.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('xc-chair-adv', 'en', array['Use this when the basic routine is easy.', 'Includes more strength and standing parts with chair support.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('xc-chair', 'en', array['Sit on a firm chair without arms, feet flat.', 'Follow along with marching, arm raises, knee straightening and gentle twists.', 'Breathe normally throughout.', 'Do the routine once a day.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('xc-chair', 'ha', array['Zauna a kan kujera mai ƙarfi mara hannu, ƙafafunka a ƙasa.', 'Bi bidiyon: taka a zaune, ɗaga hannuwa, miƙe gwiwa, da juya jiki a hankali.', 'Ka riƙa numfashi kamar yadda ka saba a kowane lokaci.', 'Yi sau ɗaya a rana.']::text[], null, null, 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('xc-chair', 'ig', array['Nọdụ n''oche siri ike nke na-enweghị aka, ụkwụ gị n''ala.', 'Soro vidiyo ahụ: zọọ ụkwụ ka ị nọ ọdụ, bulie aka, setịa ikpere, na ịtụgharị ahụ nwayọ.', 'Na-eku ume nke ọma oge niile.', 'Mee ya otu ugboro kwa ụbọchị.']::text[], null, null, 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('xc-chair', 'yo', array['Jókòó lórí àga tó le láìní ọwọ́, kí àtẹ́lẹsẹ̀ rẹ wà lórí ilẹ̀.', 'Tẹ̀lé fídíò náà: rìn ní ìjókòó, gbé apá sókè, na orúnkún, àti yíyí ara jẹ́jẹ́.', 'Máa mí dáadáa ní gbogbo ìgbà.', 'Ṣe é lẹ́ẹ̀kan lójúmọ́.']::text[], null, null, 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('xc-dram-pdf', 'en', array['NHS leaflet explaining tummy muscle separation after pregnancy.', 'Includes exercises and advice for daily activities.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('xc-dram', 'en', array['Lie on your back with knees bent.', 'Breathe out and gently draw your lower tummy in towards your spine.', 'Follow the video for gentle progressions.', 'Avoid sit-ups and crunches until your specialist says it is OK.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('xc-epley', 'en', array['Only do this if your specialist has confirmed BPPV and told you which side.', 'Sit on a bed, turn your head 45 degrees, and lie back quickly with your head slightly over a pillow.', 'Follow the video for the next head turns, waiting 30 seconds in each position.', 'Have someone with you the first time.']::text[], null, 'Stop and seek urgent help if you have a sudden severe headache, weakness, slurred speech or double vision.', 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('xc-falls', 'en', array['NHS page about falls prevention with links to strength and balance exercises.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('xc-helix', 'en', array['Printable leaflet of simple strength and balance exercises.', 'Use a sturdy support.', 'Do them at least 2 to 3 times a week.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('xc-hyper', 'en', array['Focus on control and strength, not stretching further.', 'Avoid locking the joints straight.', 'Start with small movements and build slowly.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('xc-otago', 'en', array['The Otago programme is a proven set of strength and balance exercises that reduce falls.', 'Includes knee and hip strengthening, heel and toe raises, and balance practice.', 'Always hold a sturdy support.', 'Aim for 3 times a week, plus walking.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('xc-otago', 'ha', array['Shirin Otago jerin motsa jiki ne na ƙarfi da daidaito da aka tabbatar yana rage faɗuwa.', 'Ya haɗa da ƙarfafa gwiwa da kugu, ɗaga duga-dugai da yatsun ƙafa, da koyon daidaito.', 'Koyaushe ka riƙe wani abu mai ƙarfi.', 'Yi sau uku a mako, tare da tafiya.']::text[], null, null, 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('xc-otago', 'ig', array['Usoro Otago bụ mmega ike na nguzozi egosiri na ọ na-ebelata ọdịda.', 'Ọ gụnyere ime ka ikpere na úkwù sie ike, ibuli ikiri ụkwụ na mkpịsị ụkwụ, na omume nguzozi.', 'Jide ihe siri ike mgbe niile.', 'Mee ya ugboro atọ n''izu, gbakwunye ije.']::text[], null, null, 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('xc-otago', 'yo', array['Ètò Otago jẹ́ àkójọpọ̀ eré-ìdárayá agbára àti ìdúró-déédéé tí a ti fihàn pé ó ń dín ìṣubú kù.', 'Ó ní fífún orúnkún àti ìbàdí lágbára, gbígbé gìgísẹ̀ àti ìka ẹsẹ̀ sókè, àti ìdánrawò ìdúró-déédéé.', 'Máa di nǹkan tó lágbára mú nígbà gbogbo.', 'Ṣe é ní ìgbà mẹ́ta lọ́sẹ̀, pẹ̀lú rírìn.']::text[], null, null, 'draft', 'prototype') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('xc-otago3', 'en', array['Three simple exercises from the Otago programme.', 'Hold onto a kitchen worktop or sturdy chair.', 'Do 10 repetitions of each, 3 times a week.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('xc-pgp-abuhb', 'en', array['Explains pelvic girdle pain in pregnancy and how common it is.', 'Practical advice for daily activities, sleep and moving.', 'Gentle exercises can help.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('xc-pgp-sth', 'en', array['Gentle exercises on a mat and gym ball to support the pelvis.', 'Keep knees together when moving in and out of bed or the car.', 'Stop any exercise that increases pelvic pain.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('xc-rbh-balance', 'en', array['NHS leaflet of graded balance exercises.', 'Always have support nearby.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('xc-running', 'en', array['Build strength first, then add hopping and running drills.', 'Use a walk-run programme and increase gradually.', 'Mild discomfort that settles within 24 hours is OK.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('xc-spd', 'en', array['NHS leaflet explaining pain at the front of the pelvis in pregnancy.', 'Advice on activities to avoid, sleeping and moving.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.item_guides (item_id, lang, steps, feel, stop, status, drafted_by) values ('xc-stroke', 'en', array['Seated and lying leg exercises guided by a physical therapist.', 'Have someone nearby for safety.', 'Move slowly and use the stronger side to help if needed.', 'Do 10 repetitions of each.']::text[], null, null, 'reviewed', 'human') on conflict (item_id, lang) do nothing;
insert into public.red_flags (region, lang, items, status) values ('general', 'en', array['Fever, night sweats or feeling generally unwell with your pain', 'Weight loss you cannot explain', 'A history of cancer and new pain', 'A new injury, fall or accident', 'New numbness, weakness or pins and needles that is spreading', 'Severe pain that does not stop, even at night and at rest']::text[], 'reviewed') on conflict (region, lang) do nothing;
insert into public.red_flags (region, lang, items, status) values ('general', 'yo', array['Ibà, òógùn òru, tàbí àìlera gbogbo ara pẹ̀lú ìrora rẹ', 'Rírù tí o kò mọ ìdí rẹ̀', 'Ìtàn àrùn jẹjẹrẹ àti ìrora tuntun', 'Ìpalára tuntun, ìṣubú tàbí ìjàǹbá', 'Ara kíkú tuntun, àìlágbára tàbí ìtawìrìwìrì tí ó ń tàn kálẹ̀', 'Ìrora líle tí kò dáwọ́ dúró, kódà ní òru àti nígbà ìsinmi']::text[], 'draft') on conflict (region, lang) do nothing;
insert into public.red_flags (region, lang, items, status) values ('general', 'ig', array['Ahụ ọkụ, ọsụsọ abalị, ma ọ bụ ahụ erughị ala n''ozuzu ya na mgbu gị', 'Ịda ahụ ị na-amaghị ihe kpatara ya', 'Akụkọ ọrịa kansa na mgbu ọhụrụ', 'Mmerụ ahụ ọhụrụ, ọdịda ma ọ bụ ihe mberede', 'Ahụ ịnwụ anwụ ọhụrụ, adịghị ike ma ọ bụ ịta ọkụ ọkụ na-agbasa', 'Mgbu siri ike na-adịgide, ọbụlagodi n''abalị na mgbe ị na-ezu ike']::text[], 'draft') on conflict (region, lang) do nothing;
insert into public.red_flags (region, lang, items, status) values ('general', 'ha', array['Zazzaɓi, zufar dare, ko rashin lafiya gaba ɗaya tare da ciwonka', 'Rage nauyi da ba ka san dalilinsa ba', 'Tarihin ciwon daji da sabon ciwo', 'Sabon rauni, faɗuwa ko haɗari', 'Sabon dushewa, rauni ko tsinkewa da ke yaɗuwa', 'Ciwo mai tsanani da baya tsayawa, ko da dare ko lokacin hutu']::text[], 'draft') on conflict (region, lang) do nothing;
insert into public.red_flags (region, lang, items, status) values ('thoracic', 'en', array['Chest pain, chest tightness or difficulty breathing', 'Fever, night sweats or feeling generally unwell with your pain', 'Weight loss you cannot explain', 'A history of cancer and new pain', 'A new injury, fall or accident', 'New numbness, weakness or pins and needles that is spreading', 'Severe pain that does not stop, even at night and at rest']::text[], 'reviewed') on conflict (region, lang) do nothing;
insert into public.red_flags (region, lang, items, status) values ('thoracic', 'yo', array['Ìrora àyà, àyà líle tàbí ìṣòro mímí', 'Ibà, òógùn òru, tàbí àìlera gbogbo ara pẹ̀lú ìrora rẹ', 'Rírù tí o kò mọ ìdí rẹ̀', 'Ìtàn àrùn jẹjẹrẹ àti ìrora tuntun', 'Ìpalára tuntun, ìṣubú tàbí ìjàǹbá', 'Ara kíkú tuntun, àìlágbára tàbí ìtawìrìwìrì tí ó ń tàn kálẹ̀', 'Ìrora líle tí kò dáwọ́ dúró, kódà ní òru àti nígbà ìsinmi']::text[], 'draft') on conflict (region, lang) do nothing;
insert into public.red_flags (region, lang, items, status) values ('thoracic', 'ig', array['Mgbu obi, obi isi ike ma ọ bụ nsogbu iku ume', 'Ahụ ọkụ, ọsụsọ abalị, ma ọ bụ ahụ erughị ala n''ozuzu ya na mgbu gị', 'Ịda ahụ ị na-amaghị ihe kpatara ya', 'Akụkọ ọrịa kansa na mgbu ọhụrụ', 'Mmerụ ahụ ọhụrụ, ọdịda ma ọ bụ ihe mberede', 'Ahụ ịnwụ anwụ ọhụrụ, adịghị ike ma ọ bụ ịta ọkụ ọkụ na-agbasa', 'Mgbu siri ike na-adịgide, ọbụlagodi n''abalị na mgbe ị na-ezu ike']::text[], 'draft') on conflict (region, lang) do nothing;
insert into public.red_flags (region, lang, items, status) values ('thoracic', 'ha', array['Ciwon ƙirji, matsewar ƙirji ko wahalar numfashi', 'Zazzaɓi, zufar dare, ko rashin lafiya gaba ɗaya tare da ciwonka', 'Rage nauyi da ba ka san dalilinsa ba', 'Tarihin ciwon daji da sabon ciwo', 'Sabon rauni, faɗuwa ko haɗari', 'Sabon dushewa, rauni ko tsinkewa da ke yaɗuwa', 'Ciwo mai tsanani da baya tsayawa, ko da dare ko lokacin hutu']::text[], 'draft') on conflict (region, lang) do nothing;
insert into public.red_flags (region, lang, items, status) values ('neck', 'en', array['A recent injury, fall or accident to the neck', 'Pins and needles or weakness in both arms', 'Dizziness, fainting or sudden falls', 'Trouble speaking or swallowing, or slurred speech', 'Double vision, flickering eyes, or numbness of the face', 'A sudden, severe headache unlike any before', 'Feeling sick, ringing in the ears or blurred vision with neck pain']::text[], 'reviewed') on conflict (region, lang) do nothing;
insert into public.red_flags (region, lang, items, status) values ('neck', 'yo', array['Ìpalára, ìṣubú tàbí ìjàǹbá tuntun sí ọrùn', 'Ìtawìrìwìrì tàbí àìlágbára ní apá méjèèjì', 'Òòyì, dídákú tàbí ṣíṣubú lójijì', 'Ìṣòro sísọ̀rọ̀ tàbí gbígbé oúnjẹ mì, tàbí ọ̀rọ̀ tí kò yé', 'Ríran méjì, ojú tí ń mì, tàbí ojú kíkú', 'Orí fífọ́ líle lójijì tí o kò tíì ní irú rẹ̀ rí', 'Ìríra, ariwo ní etí tàbí ríran ṣókùnkùn pẹ̀lú ìrora ọrùn']::text[], 'draft') on conflict (region, lang) do nothing;
insert into public.red_flags (region, lang, items, status) values ('neck', 'ig', array['Mmerụ ahụ, ọdịda ma ọ bụ ihe mberede ọhụrụ n''olu', 'Ịta ọkụ ọkụ ma ọ bụ adịghị ike n''aka abụọ', 'Isi ọgbụgba, ịda mbà ma ọ bụ ịda na mberede', 'Nsogbu ikwu okwu ma ọ bụ ilo nri, ma ọ bụ okwu na-adịghị edo', 'Ịhụ ihe abụọ, anya na-ama jijiji, ma ọ bụ ihu ịnwụ anwụ', 'Isi ọwụwa siri ike na mberede nke ị na-enwetụbeghị', 'Agbọ, ụda na ntị ma ọ bụ anya na-ajọ ya na mgbu olu']::text[], 'draft') on conflict (region, lang) do nothing;
insert into public.red_flags (region, lang, items, status) values ('neck', 'ha', array['Sabon rauni, faɗuwa ko haɗari a wuya', 'Tsinkewa ko rauni a hannaye biyu', 'Jiri, suma ko faɗuwa ba zato', 'Wahalar magana ko haɗiye abinci, ko magana mara kyau', 'Ganin abu biyu, idanu masu rawa, ko dushewar fuska', 'Ciwon kai mai tsanani ba zato wanda baka taɓa yi ba', 'Tashin zuciya, ƙara a kunne ko dushewar gani tare da ciwon wuya']::text[], 'draft') on conflict (region, lang) do nothing;
insert into public.red_flags (region, lang, items, status) values ('lowback', 'en', array['Numbness around your bottom, genitals or inner thighs (the saddle area)', 'New trouble passing urine, or leaking urine or stool', 'New problems with sexual function', 'Pain, numbness or weakness going down both legs', 'Legs getting weaker, or walking getting harder', 'A recent fall or injury to the back']::text[], 'reviewed') on conflict (region, lang) do nothing;
insert into public.red_flags (region, lang, items, status) values ('lowback', 'yo', array['Ara kíkú ní àyíká ìdí, ẹ̀yà ìbímọ tàbí inú itan', 'Ìṣòro tuntun láti tọ̀, tàbí ìtọ̀ tàbí ìgbẹ́ tí ń jò', 'Ìṣòro tuntun nípa ìbálòpọ̀', 'Ìrora, ara kíkú tàbí àìlágbára tí ń lọ sí ẹsẹ̀ méjèèjì', 'Ẹsẹ̀ tí ń rẹ̀wẹ̀sì sí i, tàbí ìṣòro rírìn tí ń burú sí i', 'Ìṣubú tàbí ìpalára tuntun sí ẹ̀yìn']::text[], 'draft') on conflict (region, lang) do nothing;
insert into public.red_flags (region, lang, items, status) values ('lowback', 'ig', array['Ahụ ịnwụ anwụ gburugburu ike, akụkụ nzuzo ma ọ bụ ime apata', 'Nsogbu ọhụrụ ịgba mamịrị, ma ọ bụ mamịrị ma ọ bụ nsị na-agbapụ', 'Nsogbu ọhụrụ gbasara mmekọ nwoke na nwanyị', 'Mgbu, ahụ ịnwụ anwụ ma ọ bụ adịghị ike na-agbada n''ụkwụ abụọ', 'Ụkwụ na-adịwanye ike, ma ọ bụ nsogbu ije na-aka njọ', 'Ọdịda ma ọ bụ mmerụ ahụ ọhụrụ n''azụ']::text[], 'draft') on conflict (region, lang) do nothing;
insert into public.red_flags (region, lang, items, status) values ('lowback', 'ha', array['Dushewa a kewayen ɗuwawu, al''aura ko cikin cinya', 'Sabuwar wahalar fitsari, ko zubar fitsari ko bayan gida', 'Sababbin matsaloli na jima''i', 'Ciwo, dushewa ko rauni da ke sauka zuwa ƙafafu biyu', 'Ƙafafu suna ƙara rauni, ko wahalar tafiya da ke ƙaruwa', 'Sabuwar faɗuwa ko rauni a baya']::text[], 'draft') on conflict (region, lang) do nothing;
